import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
	withoutHtmlComments,
} from "../lib/references.ts";
// Precompute FACTS for states-how-to-verify-the-change: what kind of change this is, and where
// guidance-shaped text sits. The occasion gate is where a small model slips most (a diagram or a
// self-introduction judged as lacking instructions), so the facts it needs for that gate
// are stated up front. Nothing here is a verdict — the model reads the sources and judges.
import { readLinkedWorkItemCapture } from "../lib/review.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const IMAGE = /\.(?:png|jpe?g|gif|svg|webp|pdf)$/iu;
const DIAGRAM_PATH = /(?:^|\/)(?:diagrams?|uml|models?|architecture)\//iu;
const DIAGRAM_JSON = /\.(?:json|drawio|puml|plantuml|mmd)$/iu;
const PROSE = /\.(?:md|markdown|txt|rst|adoc)$/iu;
const PROJECT_CONFIG =
	/(?:^|\/)(?:project\.yml|project\.yaml|package\.json|Package\.swift|Package\.resolved|Podfile|Cartfile|build\.gradle(?:\.kts)?|pom\.xml|pyproject\.toml|requirements\.txt|\.gitignore|\.editorconfig|\.swiftlint\.yml|Info\.plist)$/iu;
const TEST_PATH =
	/(?:^|\/)(?:tests?|specs?|__tests__)(?:\/)|[._-](?:test|tests|spec|specs)\.[a-z]+$|Tests?\.[a-z0-9]+$|Spec\.[a-z0-9]+$/iu;
const CODE = /\.(?:swift|ts|tsx|js|jsx|py|java|kt|go|rb|cs|cpp|cc|cxx|c|m|mm|h|hpp|vue|dart|rs)$/iu;
const PREVIEW = /^\+.*(?:#Preview\b|PreviewProvider\b|\.stories\.[jt]sx?|storiesOf\()/u;
// A CommonMark heading may be indented by up to three spaces.
const TESTING_HEADING =
	/^ {0,3}#+\s*(?:testing|test(?:ing)? instructions|how to test|verification|steps to (?:test|verify|reproduce))/iu;
const PLACEHOLDER_TESTING_TEXT = /^(?:n\/?a|none|not applicable|-|—)\.?$/iu;
const SCREENSHOT = /!\[[^\]]*\]\([^)]*\)/gu;
// Xcode's library inserts these around a control's defaults until the author replaces them.
const PLACEHOLDER_TOKEN = /\/\*@(?:START_MENU_TOKEN|PLACEHOLDER=)/u;
// A key or secret the code reads at runtime: a secret-shaped name beside a runtime lookup.
const SECRET_NAME =
	/api[_-]?key|apikey|client[_-]?secret|\bsecrets?\b|secret[A-Z_]|access[_-]?token/iu;
const RUNTIME_LOOKUP =
	/Bundle\.main|ProcessInfo|\benvironment\[|\.plist|xcconfig|Keychain|SecItem|UserDefaults|infoDictionary|process\.env|System\.getenv|os\.environ/u;

/** The section under a testing heading, stripped of template comments; empty when it holds nothing. */
function testingSection(body: string): { heading: string; content: string } | null {
	const lines = body.split(/\r?\n/u);
	for (let index = 0; index < lines.length; index += 1) {
		const line = lines[index] ?? "";
		if (!TESTING_HEADING.test(line)) {
			continue;
		}
		const level = (/#+/u.exec(line)?.[0] ?? "#").length;
		const content: string[] = [];
		for (let next = index + 1; next < lines.length; next += 1) {
			const candidate = lines[next] ?? "";
			const nextLevel = /^ {0,3}(?<hashes>#+)\s/u.exec(candidate)?.groups?.hashes?.length;
			if (nextLevel !== undefined && nextLevel <= level) {
				break;
			}
			content.push(candidate);
		}
		const text = withoutHtmlComments(content.join("\n")).trim();
		return { heading: line.trim(), content: text };
	}
	return null;
}

/** `path:line, line` for each file with a matching added line. */
function addedLinesMatching(
	diffFiles: Map<string, DiffFile>,
	matches: (path: string, line: string) => boolean,
): string[] {
	return [...diffFiles.values()].flatMap((file) => {
		const lines = [...file.addedLines]
			.filter(([, line]) => matches(file.path, line))
			.map(([number]) => String(number));
		return lines.length === 0 ? [] : [`${file.path}:${lines.join(", ")}`];
	});
}

export default async function statesHowToVerifyTheChange(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir?: string,
) {
	const paths = [...diffFiles.keys()];
	// A move, a rename or a binary file changes no line; an image among them is still content.
	const unchanged = [...diffFiles.values()]
		.filter(
			(file) => file.hunks.length === 0 && file.addedLines.size + file.removedLines.size === 0,
		)
		.map((file) => file.path)
		.filter((path) => !IMAGE.test(path));
	const content = paths.filter((path) => !unchanged.includes(path));
	const kinds = {
		images: content.filter((path) => IMAGE.test(path)).length,
		diagramFiles: content.filter(
			(path) =>
				DIAGRAM_PATH.test(path) ||
				(DIAGRAM_JSON.test(path) && /diagram|aom|uml|model/iu.test(path)),
		).length,
		prose: content.filter((path) => PROSE.test(path)).length,
		projectConfig: content.filter((path) => PROJECT_CONFIG.test(path)).length,
		tests: content.filter((path) => TEST_PATH.test(path)).length,
		code: content.filter((path) => CODE.test(path) && !TEST_PATH.test(path)).length,
	};
	const addedLines = [...diffFiles.values()].reduce((sum, file) => sum + file.addedLines.size, 0);
	const removedLines = [...diffFiles.values()].reduce(
		(sum, file) => sum + file.removedLines.size,
		0,
	);
	const previews = [...diffFiles.values()].filter((file) =>
		[...file.addedLines.values()].some((line) => PREVIEW.test(`+${line}`)),
	);
	const placeholders = addedLinesMatching(diffFiles, (_path, line) => PLACEHOLDER_TOKEN.test(line));
	const secretReads = addedLinesMatching(
		diffFiles,
		(path, line) =>
			!path.endsWith(".gitignore") && SECRET_NAME.test(line) && RUNTIME_LOOKUP.test(line),
	);
	const ignoredSecrets = [...diffFiles.values()]
		.filter((file) => file.path.endsWith(".gitignore"))
		.flatMap((file) => [...file.addedLines.values()])
		.map((line) => line.trim())
		.filter((line) => SECRET_NAME.test(line) || /\.xcconfig$|\.env\b/iu.test(line));

	const body = typeof metadata.body === "string" ? metadata.body : "";
	const testing = testingSection(body);
	const screenshots = body.match(SCREENSHOT)?.length ?? 0;
	// Only the author's own words adopt an issue: a closing keyword in their prose, the title, the
	// branch, or the provider's closing link. A template's example in code or a comment names nothing.
	const capture = await readLinkedWorkItemCapture(contextDir);
	const captured = capture?.items.map((item) => item.number) ?? [];
	const named = new Map<number, string[]>();
	const name = (how: string, numbers: number[]) => {
		for (const n of numbers) {
			named.set(n, [...(named.get(n) ?? []), how]);
		}
	};
	name(
		"provider closing link",
		(capture?.items ?? [])
			.filter((item) => item.how === "closesOnMerge")
			.map((item) => item.number),
	);
	name("closing keyword in the description", closingReferences(body));
	name("title", issueNumberReferences(metadata.title ?? ""));
	name("branch", branchIssueReferences(metadata.source_branch));

	const directions: string[] = [];
	if (paths.length === 0 || addedLines + removedLines === 0) {
		directions.push(
			"The pinned range changes no lines: an empty diff is one of the kinds the criteria's Occasion section names; cite it through metadata.json changed_files or work/change/files.json.",
		);
	} else if (kinds.code === 0 && kinds.tests === 0 && kinds.projectConfig === 0) {
		directions.push(
			`No code, test or project-configuration file has line changes; the change is ${kinds.images} image(s), ${kinds.diagramFiles} diagram file(s) and ${kinds.prose} prose file(s). Read the prose hunks: if they add setup or run instructions the change is material; if they add an introduction, a glossary, user stories or a diagram's embedding, it is one of the kinds the criteria's Occasion section names.`,
		);
	} else {
		directions.push(
			`Files with line changes: ${kinds.code} code, ${kinds.tests} test, ${kinds.projectConfig} project-configuration, ${kinds.prose} prose, ${kinds.images} image.`,
		);
	}
	if (unchanged.length > 0) {
		directions.push(
			`${unchanged.length} file(s) change no line — moves, renames or binary files: ${unchanged.slice(0, 5).join(", ")}${unchanged.length > 5 ? ", …" : ""}.`,
		);
	}
	// A bare testing section reads as "nothing anywhere" unless the direction says what it settles.
	const elsewhere =
		" That settles nothing either way: the entry, action and expected result can be in other sections, an adopted issue, a preview, the documented setup or the author's discussion.";
	if (testing === null) {
		directions.push(`The description has no testing heading.${elsewhere}`);
	} else if (testing.content.length === 0) {
		directions.push(
			`The description's testing heading ("${testing.heading}") has no content beneath it once template comments are removed.${elsewhere}`,
		);
	} else if (PLACEHOLDER_TESTING_TEXT.test(testing.content)) {
		directions.push(
			`The description's testing section ("${testing.heading}") holds only "${testing.content}".${elsewhere}`,
		);
	} else {
		directions.push(
			`The description's testing section ("${testing.heading}") holds ${testing.content.split(/\r?\n/u).filter((line) => line.trim()).length} line(s) of author text.`,
		);
	}
	if (named.size > 0) {
		directions.push(
			`Issue(s) the author names: ${[...named].map(([n, how]) => `#${n} (${how.join(", ")})`).join("; ")}.`,
		);
	}
	const unnamed = captured.filter((n) => !named.has(n));
	if (unnamed.length > 0) {
		directions.push(
			`Captured as linked_work_items/<n>.md but not named by a closing keyword, the title, the branch or a provider closing link: ${unnamed.map((n) => `#${n}`).join(", ")}.`,
		);
	}
	const uncaptured = [...named.keys()].filter((n) => !captured.includes(n));
	if (capture !== null && uncaptured.length > 0) {
		directions.push(
			`Named by the author but not captured: ${uncaptured.map((n) => `#${n}`).join(", ")}.`,
		);
	}
	if (previews.length > 0) {
		directions.push(
			`The patch adds an authored preview or story in: ${previews.map((file) => file.path).join(", ")}.`,
		);
	}
	if (placeholders.length > 0) {
		directions.push(`Added lines keep Xcode placeholder tokens: ${placeholders.join("; ")}.`);
	}
	if (secretReads.length > 0 || ignoredSecrets.length > 0) {
		directions.push(
			`Added lines read a key or secret at runtime: ${secretReads.join("; ") || "none"}.${ignoredSecrets.length > 0 ? ` The ignore file gains: ${ignoredSecrets.join(", ")}.` : ""}`,
		);
	}
	if (screenshots > 0) {
		directions.push(
			`The description embeds ${screenshots} image(s); read their captions and the sentences around them — the image bytes are not available to you.`,
		);
	}
	return {
		hints: [],
		metrics: {
			changedFiles: paths.length,
			filesWithoutLineChanges: unchanged.length,
			addedLines,
			removedLines,
			imageFiles: kinds.images,
			diagramFiles: kinds.diagramFiles,
			proseFiles: kinds.prose,
			projectConfigFiles: kinds.projectConfig,
			testFiles: kinds.tests,
			codeFiles: kinds.code,
			previewFiles: previews.length,
			screenshotsInDescription: screenshots,
			testingSectionLines: testing
				? testing.content.split(/\r?\n/u).filter((line) => line.trim()).length
				: 0,
			linkedIssues: captured.length,
			namedIssues: named.size,
			secretReadLines: secretReads.length,
		},
		directions,
	};
}

// Precompute traceability hints and checklist facts; the model judges readiness from the captured handoff.
import { readCommits } from "../lib/change.ts";
import { branchIssueReferences, issueNumberReferences } from "../lib/references.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default async function readyAndTraceableHandoff(
	_repoPath: string,
	_d: Map<string, DiffFile>,
	m: PullRequestMetadata,
	contextDir?: string,
) {
	const directions: string[] = [];

	// Traceability: does the handoff reference a motivating issue at all?
	const commits = await readCommits(contextDir);
	const body = `${m.body ?? ""}\n${commits.map((c) => c.message).join("\n")}`;
	const branch = m.source_branch;
	const bodyRefs = new Set(issueNumberReferences(body).map((n) => `#${n}`));
	const branchRefs = new Set(branchIssueReferences(branch).map((n) => `#${n}`));
	const allRefs = new Set<string>([...bodyRefs, ...branchRefs]);
	if (allRefs.size > 0) {
		directions.push(
			`Issue-mention syntax candidates: ${[...allRefs].join(", ")}${branchRefs.size > 0 ? ` (branch '${branch}' encodes ${[...branchRefs].join(", ")})` : ""}. Inspect each mention in context before treating it as the author's motivating issue: templates, examples and branch numbers may be unrelated. A genuine reference need not contain a closing keyword.`,
		);
	} else {
		directions.push(
			`Traceability fact: no issue reference (#N, 'Refs #N', closing keyword, or issue-number branch prefix) was found in the body, the ${commits.length} commit message(s), or branch '${branch}' — confirm in the body before concluding the handoff is untraceable.`,
		);
	}

	// Readiness: the checklist as written, counted, so a tick is never guessed at. The counts cannot say whose
	// lines they are; the model reads that from the description.
	const description = m.body ?? "";
	const ticked = (description.match(/^\s*[-*+]\s*\[[xX]\]/gmu) ?? []).length;
	const unticked = (description.match(/^\s*[-*+]\s*\[ \]/gmu) ?? []).length;
	if (ticked + unticked > 0) {
		directions.push(
			`Checklist fact: the description carries ${ticked} ticked and ${unticked} unticked checkbox line(s). These counts say neither whose lines they are nor what was done. Where work/change/description.authored.md exists, it separates the form's lines from the author's; otherwise compare description.md with the form. Judge whether the author adopted the checklist or wrote equivalent prose; a form's line left unticked as supplied is boilerplate, not unfinished work, and a tick is a claim, not a result.`,
		);
	}

	return {
		hints: [],
		metrics: {
			issueMentionSyntaxCandidateCount: allRefs.size,
			commitCount: commits.length,
			checklistTicked: ticked,
			checklistUnticked: unticked,
		},
		directions,
	};
}

// Subject clarity reads authored subject text and its shapes from the captured commit record.
import { readCapturedCommits } from "../lib/change.ts";
import { describeCommitCount, subjectFacts, subjectRows } from "../lib/commit-subjects.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default async function commitSubjectsExplainEachChange(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const captured = await readCapturedCommits(contextDir);
	const facts = subjectFacts(captured ?? []);
	const authored = facts.filter((f) => !f.merge);
	let directions = [
		describeCommitCount(facts),
		"Judge every subject on whether it names a specific action and object for a reader of the history. A flag names a shape to check, not a lapse.",
	];
	if (captured === null) {
		directions = [
			"commits.json is missing or malformed: a collection gap, not a history without authored commits.",
		];
	} else if (authored.length === 0) {
		directions = ["No authored commit in the reviewed range: only merge commits, or none."];
	}
	return {
		hints: subjectRows(facts, contextReference),
		metrics:
			captured === null
				? {}
				: {
						authoredCommits: authored.length,
						mergeCommits: facts.length - authored.length,
						bareSubjects: authored.filter((f) => f.bare).length,
						repeatedSubjects: authored.filter((f) => f.repeat).length,
						cutOffSubjects: authored.filter((f) => f.cutOff).length,
					},
		directions,
	};
}

// Surface linked-issue references and acceptance-criteria blocks, not compliance verdicts.
import { readContextJson } from "../lib/context.ts";
import { isJsonObject } from "../lib/practice-contract.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const CLOSE_KEYWORD = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\b/giu;
// "closes #12", "fixes GH-12", "resolves group/proj#12" — capture the trailing issue number.
const CLOSE_REF =
	/\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*:?\s+(?:[\w./~-]*[#!]|GH-)(?<number>\d+)/giu;
// Full issue/MR URLs on either host: .../issues/12, .../-/issues/12.
const ISSUE_URL = /https?:\/\/[^\s)]+?\/(?:-\/)?issues\/(?<number>\d+)/giu;
// Issue number embedded in a branch name: feature/123-foo, issue-123, 123-fix-thing, bugfix/GH-123.
const BRANCH_REF = /(?:^|[/_-])(?:issue[-_]?|gh[-_]?|#)?(?<number>\d{1,6})(?:[-_/]|$)/giu;

// Every pattern below is global and captures the issue number in group 1; matchAll iterates a clone,
// so the shared module-level regexes keep a lastIndex of 0 between calls.
function collect(re: RegExp, text: string, into: Set<string>): void {
	if (!text) {
		return;
	}
	re.lastIndex = 0;
	for (const match of text.matchAll(re)) {
		into.add(`#${match.groups?.number ?? ""}`);
	}
}

interface LinkedWorkItem {
	number?: number | string;
	iid?: number | string;
	title?: string;
	// The SCM connector (LinkedWorkItemContentSource) emits the issue body under `body`; `description`
	// is a host-general fallback for other connectors.
	body?: string;
	description?: string;
}

function optionalText(value: unknown): string | undefined {
	return typeof value === "string" ? value : undefined;
}

function optionalRef(value: unknown): number | string | undefined {
	return typeof value === "number" || typeof value === "string" ? value : undefined;
}

// An entry carrying none of the fields above still counts as a linked item: `linkedIssueCount` reports
// how many items the connector linked, which is a fact about the tracker, not about how much of each
// entry this side could read.
function toLinkedWorkItem(entry: unknown): LinkedWorkItem {
	if (!isJsonObject(entry)) {
		return {};
	}
	return {
		number: optionalRef(entry.number),
		iid: optionalRef(entry.iid),
		title: optionalText(entry.title),
		body: optionalText(entry.body),
		description: optionalText(entry.description),
	};
}

// Unwrap whatever shape linked_work_items.json carries into a flat item list (or null if not a usable object).
function unwrapLinkedItems(data: unknown): LinkedWorkItem[] | null {
	if (Array.isArray(data)) {
		return data.map(toLinkedWorkItem);
	}
	if (!isJsonObject(data)) {
		return null;
	}
	// The SCM connector wraps items under `workItems`; check it FIRST, then host-general fallbacks.
	if (Array.isArray(data.workItems)) {
		return data.workItems.map(toLinkedWorkItem);
	}
	if (Array.isArray(data.items)) {
		return data.items.map(toLinkedWorkItem);
	}
	return [toLinkedWorkItem(data)];
}

// A checkable acceptance-criteria artifact: an AC/DoD heading or a "- [ ]" checklist in the issue body.
function acFacts(body: string): { heading: boolean; boxes: number } {
	const heading =
		/(?:acceptance criteria|definition of done|\bDoD\b|done when|expected (?:outcome|result|behaviou?r))/iu.test(
			body,
		);
	const boxes = (body.match(/^[\s>]*[-*]\s+\[[ xX]\]/gmu) ?? []).length;
	return { heading, boxes };
}

export default async function honoursLinkedIssueAcceptanceCriteria(
	_repoPath: string,
	_diff: Map<string, DiffFile>,
	meta: PullRequestMetadata,
	contextDir?: string,
) {
	const title = meta.title ?? "";
	const body = meta.body ?? "";
	const branch = meta.source_branch;

	// Syntax matches are candidates, including examples and code spans. They establish neither a
	// provider-reported relationship nor adoption of another issue's criteria by the author.
	const refs = new Set<string>();
	collect(CLOSE_REF, `${title}\n${body}`, refs);
	collect(ISSUE_URL, `${title}\n${body}`, refs);
	const closingRefs = [...refs];
	const hasClosingRef = closingRefs.length > 0;

	const branchRefSet = new Set<string>();
	collect(BRANCH_REF, branch, branchRefSet);
	const branchRefs = [...branchRefSet];
	const hasBranchRef = branchRefs.length > 0;

	const keywordHits = (`${title}\n${body}`.match(CLOSE_KEYWORD) ?? []).length;
	CLOSE_KEYWORD.lastIndex = 0;

	const linked = unwrapLinkedItems(await readContextJson(contextDir, "linked_work_items.json"));
	const linkedIssueBodyPresent = linked?.some(
		(i) => (i.body ?? i.description ?? "").trim().length > 0,
	);
	let acHeading = false;
	let acBoxes = 0;
	if (linked) {
		for (const i of linked) {
			const f = acFacts((i.body ?? i.description ?? "").trim());
			acHeading ||= f.heading;
			acBoxes += f.boxes;
		}
	}
	const hasCheckableAcBlock = acHeading || acBoxes > 0;

	const directions: string[] = [];
	if (hasClosingRef) {
		directions.push(
			`Issue-reference syntax candidate(s) (${closingRefs.join(", ")}) from title/body — inspect the exact mention in context, including templates/examples, before establishing that the author claims to close this issue. Only then map those criteria to the change.`,
		);
	} else if (hasBranchRef) {
		directions.push(
			`Branch name encodes a possible issue number (${branchRefs.join(", ")}) but no closing keyword/URL was found in title/body — treat this as a traceability candidate, not a closing claim: confirm it maps to a tracked issue before mapping any acceptance criteria.`,
		);
	} else if (keywordHits > 0) {
		directions.push(
			`Closing keyword(s) present but no issue number parsed — investigate whether a tracked issue is linked another way before treating this as having no acceptance criteria to honour.`,
		);
	} else {
		directions.push(
			`No closing reference, issue URL, or branch-encoded number found in title/body/branch — confirm there is genuinely no linked tracker issue before concluding there are no acceptance criteria to honour.`,
		);
	}

	if (linked === null) {
		directions.push(
			`No linked_work_items.json was projected into context — the linked issue's body and its acceptance-criteria block are NOT visible here, so this practice cannot be assessed from the diff alone.`,
		);
	} else if (linkedIssueBodyPresent === true) {
		directions.push(
			`Candidate issue facts: bodyPresent=true, acceptanceCriteriaBlockPresent=${hasCheckableAcBlock} (heading=${acHeading}, checkboxes=${acBoxes}) — these are text facts, not applicability. Confirm an authored closing claim in the original mention context before mapping criteria to done or deferred.`,
		);
	} else {
		directions.push(
			`Linked-issue context exists but carries no issue body — there is no quotable acceptance-criteria text to map the change against.`,
		);
	}

	return {
		hints: [],
		metrics: {
			issueReferenceSyntaxCandidateCount: closingRefs.length,
			hasIssueReferenceSyntaxCandidate: hasClosingRef ? 1 : 0,
			branchRefCount: branchRefs.length,
			hasBranchRef: hasBranchRef ? 1 : 0,
			closingKeywordHits: keywordHits,
			linkedItemsFilePresent: linked === null ? 0 : 1,
			linkedIssueCount: linked?.length ?? 0,
			linkedIssueBodyPresent: linkedIssueBodyPresent === true ? 1 : 0,
			acceptanceCriteriaBlockPresent: hasCheckableAcBlock ? 1 : 0,
			acceptanceCriteriaCheckboxes: acBoxes,
		},
		directions,
	};
}

// Precompute FACTS for engaging-with-inline-review-comments: every note by someone other than the
// author, inline and in the conversation, one row each, with what the record shows beside it — the
// author's later reply, the thread's resolution and who resolved it, the reviewer's own later note,
// whether and how soon the same reviewer approved afterwards, whether the note came after the work
// merged or closed, and the authored commits that came after it. The review decides for each row
// whether the note asked something of this change and whether the author engaged; the script never does.
import { type ChangeCommit, readCapturedCommits } from "../lib/change.ts";
import { contextFile } from "../lib/context.ts";
import {
	type GeneralComment,
	type ReviewDecision,
	changeNear,
	commitsAfter,
	excerpt,
	later,
	millisBetween,
	readGeneralComments,
	readReviewComments,
	readReviewThreads,
	reviewerCommentRows,
} from "../lib/review.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/** An instant strictly between two others; false when any is missing. */
function between(
	at: string | undefined,
	from: string | undefined,
	to: string | undefined,
): boolean {
	return later(at, from) && !later(at, to);
}

/**
 * The same reviewer's first approval at or after the note, with what came between them: advice posted
 * with an approval reads differently from an approval given after the author answered. Empty when that
 * reviewer did not approve afterwards.
 */
function approvalAfter(
	decisions: readonly ReviewDecision[],
	reviewer: string | undefined,
	at: string | undefined,
	commits: readonly ChangeCommit[] | null,
	authorNotes: readonly { createdAt?: string }[],
): string {
	const approval = decisions
		.filter(
			(d) =>
				d.state === "APPROVED" &&
				d.dismissed !== true &&
				d.author === reviewer &&
				(millisBetween(at, d.submittedAt) ?? -1) >= 0,
		)
		.toSorted((a, b) => Date.parse(a.submittedAt ?? "") - Date.parse(b.submittedAt ?? ""))[0];
	if (approval === undefined) {
		return "";
	}
	const seconds = Math.round((millisBetween(at, approval.submittedAt) ?? 0) / 1000);
	const commitsBetween = (commits ?? []).filter(
		(c) => c.parents.length < 2 && between(c.committedAt, at, approval.submittedAt),
	).length;
	const notesBetween = authorNotes.filter((n) =>
		between(n.createdAt, at, approval.submittedAt),
	).length;
	return `${String(seconds)}s later; ${commits === null ? "unknown commit count" : `${String(commitsBetween)} commit(s)`} and ${String(notesBetween)} author note(s) between`;
}

export default async function engagingWithInlineReviewComments(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const author = metadata.author ?? "";
	const inline = await readReviewComments(contextDir);
	const general = await readGeneralComments(contextDir);
	const record = await readReviewThreads(contextDir);
	const capturedCommits = await readCapturedCommits(contextDir);
	const commits = capturedCommits ?? [];
	const decisions = record?.decisions ?? [];
	const handOff = metadata.merged_at ?? metadata.closed_at;
	const byOthers = (note: { author?: string }) =>
		note.author !== undefined && note.author !== author;
	const authorNotes = [
		...(inline ?? []).filter((c) => c.author === author),
		...(general ?? []).filter((c) => c.author === author),
	];
	/** The reviewer's next conversation note after `at`, where a settling "thank you" usually sits. */
	const reviewerNextNote = (reviewer: string | undefined, at: string | undefined) =>
		(general ?? []).find((c) => c.author === reviewer && later(c.createdAt, at))?.body ?? "";

	const inlineHints: Hint[] = reviewerCommentRows(inline ?? [], record?.threads ?? [], author).map(
		({ comment, replies, followUps, thread }) => ({
			file: comment.path,
			line: comment.line ?? 0,
			pattern: "reviewer comment",
			context: excerpt(comment.body),
			inDiff: false,
			flags: {
				by: comment.author ?? "",
				bot: comment.bot,
				at: comment.createdAt ?? "",
				side: comment.side ?? "",
				outdated: comment.outdated,
				authorReplied: replies.length > 0,
				replyExcerpt: excerpt(replies.map((r) => r.body).join(" "), 80),
				threadResolved: thread?.state === "RESOLVED",
				resolvedBy: thread?.resolvedBy ?? "",
				reviewerLaterNote: excerpt(
					followUps.find((f) => f.author === comment.author)?.body ??
						reviewerNextNote(comment.author, comment.createdAt),
					80,
				),
				reviewerApprovedAfter: approvalAfter(
					decisions,
					comment.author,
					comment.createdAt,
					capturedCommits,
					authorNotes,
				),
				afterHandOff: later(comment.createdAt, handOff),
				fileInChange: diffFiles.has(comment.path),
				changeNearLine: changeNear(diffFiles.get(comment.path), comment.line),
				commitsAfter:
					capturedCommits === null ? "unknown" : commitsAfter(commits, comment.createdAt),
				commitsAfterTouchingFile:
					capturedCommits === null
						? "unknown"
						: commitsAfter(commits, comment.createdAt, comment.path),
			},
		}),
	);
	const conversationHints: Hint[] = (general ?? []).filter(byOthers).map((note: GeneralComment) => {
		const authorAfter = (general ?? []).filter(
			(c) => c.author === author && later(c.createdAt, note.createdAt),
		);
		return {
			file: contextFile(contextReference, "general_comments.json"),
			line: 0,
			pattern: "conversation comment",
			context: excerpt(note.body),
			inDiff: false,
			flags: {
				by: note.author ?? "",
				bot: note.bot,
				at: note.createdAt ?? "",
				authorNotesAfter: authorAfter.length,
				authorNoteExcerpt: excerpt(authorAfter[0]?.body ?? "", 80),
				reviewerLaterNote: excerpt(reviewerNextNote(note.author, note.createdAt), 80),
				reviewerApprovedAfter: approvalAfter(
					decisions,
					note.author,
					note.createdAt,
					capturedCommits,
					authorNotes,
				),
				afterHandOff: later(note.createdAt, handOff),
				commitsAfter: capturedCommits === null ? "unknown" : commitsAfter(commits, note.createdAt),
			},
		};
	});
	const hints = [...inlineHints, ...conversationHints];
	const byPeople = hints.filter((h) => h.flags.bot !== true);
	const replied = byPeople.filter(
		(h) => h.flags.authorReplied === true || Number(h.flags.authorNotesAfter) > 0,
	).length;
	// Without the commit record each note's count is unknown, and so is their sum: never a measured 0.
	const committedAfter =
		capturedCommits === null
			? null
			: byPeople.filter((h) => Number(h.flags.commitsAfterTouchingFile) > 0).length;
	const afterHandOff = byPeople.filter((h) => h.flags.afterHandOff === true).length;
	const directions: string[] = [];
	if (inline === null && general === null) {
		directions.push(
			"No comments file was captured (neither comments.json nor general_comments.json): the record of reviewer notes is not available here.",
		);
	} else if (hints.length === 0) {
		directions.push(
			`No note by anyone other than the author in the captured record (${inline === null ? "comments.json not captured" : `${String(inline.length)} inline comment(s)`}, ${general === null ? "general_comments.json not captured" : `${String(general.length)} conversation comment(s)`}).`,
		);
	} else {
		const bots = hints.length - byPeople.length;
		directions.push(
			`${String(byPeople.length)} reviewer note(s) (${String(inlineHints.filter((h) => h.flags.bot !== true).length)} inline, ${String(conversationHints.filter((h) => h.flags.bot !== true).length)} conversation)${bots > 0 ? `, ${String(bots)} more by bots` : ""}; ${String(replied)} have a later author note; ${committedAfter === null ? "how many have a later authored commit touching the commented file is unknown" : `${String(committedAfter)} have a later authored commit touching the commented file`}; ${String(afterHandOff)} were posted after the work merged or closed. Commit capture: ${capturedCommits === null ? "unavailable" : `${String(commits.length)} captured commit(s)`} in ${contextFile(contextReference, "commits.json")}.`,
		);
	}
	return {
		hints,
		metrics: {
			commentsFileAbsent: inline === null ? 1 : 0,
			generalCommentsFileAbsent: general === null ? 1 : 0,
			reviewerComments: inlineHints.filter((h) => h.flags.bot !== true).length,
			conversationComments: conversationHints.filter((h) => h.flags.bot !== true).length,
			botComments: hints.length - byPeople.length,
			withAuthorReply: replied,
			...(committedAfter === null ? {} : { withLaterCommitOnFile: committedAfter }),
			afterHandOff,
			commitsFileAbsent: capturedCommits === null ? 1 : 0,
		},
		directions,
	};
}

// Precompute FACTS for merged-past-unresolved-review-threads: the merge as the record holds it —
// who merged, when — and one row per review thread the record does not show resolved by the merge,
// with where it is anchored, when it was opened and whether the provider calls it outdated. The review
// reads each thread against the merge; the rows say what the record holds, not whether the merge was owed.
import {
	dated,
	mergeFacts,
	mergeRow,
	readReviewThreads,
	resolvedByMerge,
	unresolvedThreadRows,
} from "../lib/review.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default async function mergedPastUnresolvedReviewThreads(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const merge = mergeFacts(metadata);
	const mergeUndated = merge.merged && !dated(merge.mergedAt);
	const record = await readReviewThreads(contextDir);
	const threads = record?.threads ?? [];
	const unresolved = unresolvedThreadRows(threads, contextReference, merge);
	const directions: string[] = [];
	if (!merge.merged) {
		directions.push("The pull request is not merged: the occasion did not arise.");
	} else if (record === null) {
		directions.push(
			"No review threads file was captured (review_threads.json): the thread record is not available here.",
		);
	} else {
		directions.push(
			`Merged${merge.mergedBy === undefined ? "" : ` by ${merge.mergedBy}`}${merge.mergedByIsAuthor ? " (the author)" : ""}; ${threads.length} thread(s) captured, ${unresolved.length} candidate thread(s) — currently not marked RESOLVED, resolved after the merge, or resolved at a time the record does not establish — one row each.${mergeUndated ? " The record gives no usable merge time, so no resolution is placed before or after the merge." : ""} These are not proven open at merge: compare opening and resolution times, and treat an unknown historical order as UNDETERMINED. Read each thread's comments in comments.json by its id (the comments' \`thread\`) before deciding what it asked.`,
		);
	}
	return {
		hints: [mergeRow(metadata, merge, contextReference), ...unresolved],
		metrics: {
			merged: merge.merged ? 1 : 0,
			mergedByIsAuthor: merge.mergedByIsAuthor ? 1 : 0,
			threads: threads.length,
			candidateThreads: unresolved.length,
			resolutionTimeUnknown: unresolved.filter(
				(h) =>
					h.flags.state === "RESOLVED" &&
					typeof h.flags.resolvedAt === "string" &&
					!dated(h.flags.resolvedAt),
			).length,
			// Undated, the merge places no resolution before it, so the count is left out rather than zero.
			...(mergeUndated
				? {}
				: {
						resolvedBeforeMerge: threads.filter(
							(t) => t.state === "RESOLVED" && resolvedByMerge(t, merge),
						).length,
					}),
			threadsFileAbsent: record === null ? 1 : 0,
		},
		directions,
	};
}

// Precompute FACTS for issue-states-an-actionable-problem: what the captured issue carries — whether
// its body is empty or only repeats the title, its labels and its native type. Whether a maintainer
// can picture the work and start is the criteria's to decide from the whole text.
import { bodyFact, classifyIssue, type IssueMetadata } from "../lib/issue-classification.ts";
import type { Hint } from "../lib/types.ts";

export default function issueStatesAnActionableProblem(
	_repo: string,
	_diff: Map<string, unknown>,
	m: IssueMetadata,
) {
	const shape = classifyIssue(m);
	const { body, issueType, labels, emptyOrTitleEcho, hasDeliverableType, looksUmbrella } = shape;

	const directions = [
		...bodyFact(shape),
		`Captured: ${String(body.length)} body character(s); labels ${labels.join(", ") || "none"}; native type ${issueType || "none"}. Judge the standard once over the title, the whole body, the comments and any materialised document the issue delegates to.`,
	];

	const hints: Hint[] = [];
	return {
		hints,
		metrics: {
			bodyLength: body.length,
			labelCount: labels.length,
			emptyOrTitleEcho: emptyOrTitleEcho ? 1 : 0,
			hasDeliverableType: hasDeliverableType ? 1 : 0,
			looksUmbrella: looksUmbrella ? 1 : 0,
		},
		directions,
	};
}

// Precompute FACTS for issue-scoped-to-single-concern: the task-list items and issue-number mentions the
// body carries and the captured sub-issue rollup with its source. Whether the issue is one concern at its level
// is the criteria's to decide.
import {
	bodyFact,
	classifyIssue,
	subIssueRollup,
	type IssueMetadata,
} from "../lib/issue-classification.ts";
import { checkableItems } from "../lib/review.ts";
import type { Hint } from "../lib/types.ts";

export default function issueScopedToSingleConcern(
	_repo: string,
	_diff: Map<string, unknown>,
	m: IssueMetadata,
) {
	const shape = classifyIssue(m);
	const { body, labels, emptyOrTitleEcho } = shape;
	const checkboxes = checkableItems(body).length;
	const issueMentions = new Set((body.match(/(?:^|\s)#\d+\b/gu) ?? []).map((s) => s.trim())).size;
	const rollup = subIssueRollup(m);
	const directions = [
		...bodyFact(shape),
		`Captured: ${String(checkboxes)} task-list item(s), ${String(issueMentions)} issue-number mention(s), ${rollup.text}; labels ${labels.join(", ") || "none"}. Judge the standard once over the title, whole body and captured discussion; these counts locate text and decide nothing.`,
	];

	const hints: Hint[] = [];
	return {
		hints,
		metrics: {
			bodyLength: body.length,
			emptyOrTitleEcho: emptyOrTitleEcho ? 1 : 0,
			checkboxes,
			childIssueRefs: issueMentions,
			...rollup.metrics,
		},
		directions,
	};
}

// Precompute FACTS for issue-has-checkable-outcome: the task-list items the body carries and how the
// issue is labelled and typed. Whether any of the text is a finish line is the criteria's to decide.
import { bodyFact, classifyIssue, type IssueMetadata } from "../lib/issue-classification.ts";
import { checkableItems } from "../lib/review.ts";
import type { Hint } from "../lib/types.ts";

export default function issueHasCheckableOutcome(
	_repo: string,
	_diff: Map<string, unknown>,
	m: IssueMetadata,
) {
	const shape = classifyIssue(m);
	const { body, issueType, labels, emptyOrTitleEcho, hasDeliverableType, looksUmbrella } = shape;
	const items = checkableItems(body);
	const checkedBoxes = items.filter((item) => item.checked).length;

	const directions = [
		...bodyFact(shape),
		`Captured: ${String(items.length)} task-list item(s) in the body (${String(checkedBoxes)} ticked); labels ${labels.join(", ") || "none"}; native type ${issueType || "none"}. Judge the standard once over the title, the whole body, the comments and any materialised document; these counts locate text and decide nothing.`,
	];

	const hints: Hint[] = [];
	return {
		hints,
		metrics: {
			bodyLength: body.length,
			taskCheckboxes: items.length,
			uncheckedBoxes: items.length - checkedBoxes,
			checkedBoxes,
			emptyOrTitleEcho: emptyOrTitleEcho ? 1 : 0,
			hasDeliverableType: hasDeliverableType ? 1 : 0,
			looksUmbrella: looksUmbrella ? 1 : 0,
		},
		directions,
	};
}

// Precompute FACTS for ships-tests-with-the-change: which changed source files are tests and which are
// production code, by path convention. Whether a test covers the changed behaviour is the review's to
// read from the diff.
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default function shipsTestsWithTheChange(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const source = [...diffFiles.keys()].filter((path) => languageOf(path) !== null);
	const tests = source.filter((path) => isTestPath(path));
	const production = source.filter((path) => !isTestPath(path));

	const directions: string[] = [];
	if (source.length > 0) {
		directions.push(
			`The diff changes ${String(production.length)} production source file(s) and ${String(tests.length)} test file(s), by path${tests.length > 0 ? `: ${tests.slice(0, 10).join(", ")}` : ""}. Whether the repository already has a test target does not decide this practice: judge the changed behaviour against the tests in this diff.`,
		);
	}
	return {
		hints: [],
		metrics: {
			diffProductionFiles: production.length,
			diffTestFiles: tests.length,
		},
		directions,
	};
}

// Precompute FACTS for removes-duplication-instead-of-copy-pasting: every pair of added blocks
// whose lines have the same shape once names and literals are set aside — the two spans, the run
// length, how many lines are identical to the character, and the names that differ. The review
// judges each pair: a unit of knowledge written twice, or an idiom the platform makes look alike.
import { duplicatePairs, MIN_RUN_LINES } from "../lib/duplication.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const MAX_PAIRS = 20;

export default function removesDuplicationInsteadOfCopyPasting(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const sourceFiles = [...diffFiles.values()].filter(
		(file) => languageOf(file.path) !== null && !isTestPath(file.path),
	);
	const linesAdded = sourceFiles.reduce((sum, file) => sum + file.addedLines.size, 0);
	const pairs = duplicatePairs(diffFiles);
	const hints: Hint[] = pairs.slice(0, MAX_PAIRS).map((pair) => ({
		file: pair.a.path,
		line: pair.a.startLine,
		pattern: "same-shaped added blocks",
		context: `[L${String(pair.a.startLine)}]-[L${String(pair.a.endLine)}] and ${pair.b.path} [L${String(pair.b.startLine)}]-[L${String(pair.b.endLine)}]: ${String(pair.lines)} lines of one shape, ${String(pair.identicalLines)} identical`,
		inDiff: true,
		flags: {
			otherPath: pair.b.path,
			otherStart: pair.b.startLine,
			otherEnd: pair.b.endLine,
			lines: pair.lines,
			identicalLines: pair.identicalLines,
			differing: pair.differing.join(", "),
		},
	}));
	const directions =
		pairs.length === 0
			? [
					`No two runs of ${String(MIN_RUN_LINES)} or more added lines share a shape once names and literals are set aside. A copy this pairing cannot see — the same computation spelled with different statements, or shorter than ${String(MIN_RUN_LINES)} lines — is still yours to read for.`,
				]
			: [
					`${String(pairs.length)} pair(s) of added blocks with the same line shapes, one row each with both spans and the names that differ. These are structural candidates, not established copies of maintained knowledge. Assess them under the practice standard.`,
				];
	return {
		hints,
		metrics: { linesAdded, filesScanned: sourceFiles.length, pairs: pairs.length },
		directions,
	};
}

// Precompute HINTS for leaves-the-code-clean-with-intent-revealing-comments. Surfaces facts only — the LLM
// judges whether each is real residue. On a large diff the model under-scans length and misses obvious
// debug traces / leftover markers sitting right there; this points it at the exact added lines. General by
// design: a per-language debug-output token table keyed off file extension. Adding a language = a row.
// CANDIDATES, never an observation.
import { languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// language key -> [human label, regex] of debug-output / residue constructs that, when ADDED, are worth a look.
const LANG_PATTERNS: Record<string, [string, RegExp][]> = {
	swift: [
		["print(", /(?:^|[^.\w])print\s*\(/u],
		["debugPrint(", /\bdebugPrint\s*\(/u],
		["NSLog(", /\bNSLog\s*\(/u],
		["dump(", /(?:^|[^.\w])dump\s*\(/u],
	],
	typescript: [
		["console.*", /\bconsole\.(?:log|debug|info|warn|error|trace)\s*\(/u],
		["debugger", /\bdebugger\b/u],
	],
	javascript: [
		["console.*", /\bconsole\.(?:log|debug|info|warn|error|trace)\s*\(/u],
		["debugger", /\bdebugger\b/u],
	],
	python: [
		["print(", /(?:^|[^.\w])print\s*\(/u],
		["breakpoint(", /\bbreakpoint\s*\(/u],
		["pprint(", /\bpprint\s*\(/u],
	],
	java: [
		["System.out/err.print", /\bSystem\.(?:out|err)\.print/u],
		["printStackTrace(", /\.printStackTrace\s*\(/u],
	],
	kotlin: [["println(", /\bprintln\s*\(/u]],
	go: [
		["fmt.Print*", /\bfmt\.Print[a-z]*\s*\(/u],
		["println(", /(?:^|[^.\w])println\s*\(/u],
	],
	ruby: [["puts/p/pp", /(?:^|[^.\w])(?:puts|pp?)\s+["'\d:@]/u]],
	rust: [["println!/dbg!/eprintln!", /\b(?:println|eprintln|dbg|print|eprint)\s*!/u]],
};

// A TODO/FIXME/XXX/HACK marker added in the diff — a residue signal across all languages.
const TODO_MARKER = /\b(?:TODO|FIXME|XXX|HACK)\b/u;

// A comment that narrates the editing session rather than the code, on any language's comment line.
const PROCESS_NOTE =
	/^\s*(?:\/\/|#|\*)\s*(?:FIX(?:ED)?\s*\d*\s*:|CHANGED?\s*:|ADDED\s*:|MOVED\s*:|UPDATED?\s*:|REMOVED?\s*:|NEW\s*:)/iu;
// A template placeholder left in a manifest the change edited.
const TEMPLATE_PLACEHOLDER = /#\s*TODO:\s*Adjust|<your[- ]|REPLACE[_ ]ME|CHANGE[_ ]ME/iu;

export default function leavesTheCodeCleanWithIntentRevealingComments(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byLang: Record<string, number> = {};
	let debugCandidates = 0;
	let todoCandidates = 0;
	let processNotes = 0;
	let placeholders = 0;
	let scratchFiles = 0;

	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		const patterns = lang === null ? [] : (LANG_PATTERNS[lang] ?? []);
		// A file added with a line or two of content and no language is a scratch file until read.
		const added = [...df.addedLines.values()].filter((l) => l.trim().length > 0);
		if (
			lang === null &&
			df.removedLines.size === 0 &&
			added.length > 0 &&
			added.length <= 2 &&
			/\.(?:txt|md)$/iu.test(path) &&
			!/README|CHANGELOG|LICENSE/iu.test(path)
		) {
			hints.push({
				file: path,
				line: [...df.addedLines.keys()][0] ?? 1,
				pattern: "near-empty new file",
				context: added[0]?.trim().slice(0, 160) ?? "",
				inDiff: true,
				flags: { kind: "scratch" },
			});
			scratchFiles += 1;
		}
		for (const [lineNum, text] of df.addedLines) {
			// Skip lines that are themselves comments — a debug call inside a comment is not live residue.
			const trimmed = text.trim();
			const isComment = /^(?:\/\/|#|\*|\/\*)/u.test(trimmed);
			// One debug-output hint per added line, as the sibling validates-inputs script does.
			const debugOutput = isComment ? undefined : patterns.find(([, re]) => re.test(text));
			if (debugOutput !== undefined) {
				hints.push({
					file: path,
					line: lineNum,
					pattern: debugOutput[0],
					context: trimmed.slice(0, 160),
					inDiff: true,
					flags: { kind: "debug-output" },
				});
				debugCandidates += 1;
				if (lang !== null) {
					byLang[lang] = (byLang[lang] ?? 0) + 1;
				}
			}
			if (TODO_MARKER.test(text)) {
				hints.push({
					file: path,
					line: lineNum,
					pattern: "TODO/FIXME marker",
					context: trimmed.slice(0, 160),
					inDiff: true,
					flags: { kind: "marker" },
				});
				todoCandidates += 1;
			}
			if (PROCESS_NOTE.test(text)) {
				hints.push({
					file: path,
					line: lineNum,
					pattern: "editing-process note",
					context: trimmed.slice(0, 160),
					inDiff: true,
					flags: { kind: "process-note" },
				});
				processNotes += 1;
			}
			if (TEMPLATE_PLACEHOLDER.test(text)) {
				hints.push({
					file: path,
					line: lineNum,
					pattern: "template placeholder",
					context: trimmed.slice(0, 160),
					inDiff: true,
					flags: { kind: "placeholder" },
				});
				placeholders += 1;
			}
		}
	}

	const directions: string[] = [];
	if (debugCandidates > 0) {
		directions.push(
			`Found ${debugCandidates} debug-output call(s) on added lines (print/console/log-style) — investigate whether each is leftover debug residue or a deliberate, intent-revealing log.`,
		);
	}
	if (todoCandidates > 0) {
		directions.push(
			`Found ${todoCandidates} TODO/FIXME/XXX/HACK marker(s) added — investigate whether each is actionable residue or an intentional, tracked note.`,
		);
	}
	if (processNotes + placeholders + scratchFiles > 0) {
		directions.push(
			`Found ${processNotes} comment(s) narrating the editing session, ${placeholders} template placeholder(s) and ${scratchFiles} near-empty new file(s) — residue of the writing process unless the surrounding text says otherwise.`,
		);
	}
	return {
		hints: hints.slice(0, 40),
		metrics: {
			debugCandidates,
			todoCandidates,
			processNotes,
			placeholders,
			scratchFiles,
			...byLang,
		},
		directions,
	};
}

// Precompute HINTS for logs-through-the-platform-logger: the print-style and logger calls ADDED in
// application code, per language, and whether a bounded search of the checkout matches a logger. The
// closed list of print shapes and logger shapes per language mirrors the criteria; whether a print is the
// program's output (a CLI, a script) or a shipped debugging line is the review's to decide from the file.
import { grep } from "../lib/grep.ts";
import { countLabel, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

interface Shapes {
	print: SourcePattern[];
	logger: SourcePattern[];
}

const SCRIPTING: Shapes = {
	print: [["console.*", /\bconsole\.(?:log|debug|info|warn|error)\s*\(/u]],
	logger: [["logger", /\b(?:log|logger)\.(?:trace|debug|info|warn|error|fatal)\s*\(/u]],
};

// The Apple system log: NSLog and NSLogv write to it, as the os_log family does.
const APPLE_SYSTEM_LOG: SourcePattern[] = [
	["os_log", /\bos_log(?:_(?:info|debug|error|fault))?\s*\(/u],
	["NSLog", /\bNSLogv?\s*\(/u],
];

// android.util.Log at any level and whatever its tag, and Timber over it. A bare `Log.` is read by name:
// the import that makes it android.util.Log is the review's to confirm.
const ANDROID_LOG: SourcePattern[] = [
	["android.util.Log", /\b(?:android\.util\.)?Log\.(?:v|d|i|w|e|wtf)\s*\(/u],
	["Timber", /\bTimber\.(?:v|d|i|w|e|wtf)\s*\(/u],
];

// language -> the print-style shapes and the logger shapes the criteria list for it.
const DIAGNOSTICS: Record<string, Shapes> = {
	swift: {
		print: [
			["print(", /(?:^|[^\w.])print\s*\(/u],
			["debugPrint(", /\bdebugPrint\s*\(/u],
			["dump(", /(?:^|[^\w.])dump\s*\(/u],
		],
		logger: [
			[
				"Logger",
				/\bLogger\s*\(|\b(?:logger|Logger\.shared)\.(?:trace|debug|info|notice|warning|error|critical|fault|log)\s*\(/u,
			],
			...APPLE_SYSTEM_LOG,
		],
	},
	"objective-c": {
		print: [["printf(", /\bprintf\s*\(/u]],
		logger: APPLE_SYSTEM_LOG,
	},
	kotlin: {
		print: [["println(", /(?:^|[^\w.])println?\s*\(/u]],
		logger: [...ANDROID_LOG, ["logger", /\blog(?:ger)?\.(?:trace|debug|info|warn|error)\s*\(/u]],
	},
	java: {
		print: [
			["System.out/err", /\bSystem\.(?:out|err)\.print/u],
			["printStackTrace()", /\.printStackTrace\s*\(/u],
		],
		logger: [
			...ANDROID_LOG,
			["logger", /\b(?:log|logger|LOG|LOGGER)\.(?:trace|debug|info|warn|error|severe|fine)\s*\(/u],
		],
	},
	typescript: SCRIPTING,
	javascript: SCRIPTING,
	python: {
		print: [["print(", /(?:^|[^\w.])print\s*\(/u]],
		logger: [
			[
				"logging",
				/\b(?:logging|logger|log)\.(?:debug|info|warning|error|exception|critical)\s*\(/u,
			],
		],
	},
};

/** Where a print is the program's output rather than a diagnostic: the criteria's exemptions, by path. */
const TOOL_PATH =
	/(?:^|\/)(?:scripts?|tools?|bin|cli|Scripts|fastlane|ci)\/|\.(?:sh|mjs|cjs)$|(?:^|\/)main\.(?:py|ts|js)$|Playground|\.playground\//u;

export default async function logsThroughThePlatformLogger(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	let prints = 0;
	let loggers = 0;
	let filesScanned = 0;
	let linesAdded = 0;
	for (const [language, shapes] of Object.entries(DIAGNOSTICS)) {
		const scan = await scanAddedLines(repoPath, diffFiles, {
			languages: [language],
			patterns: [...shapes.print, ...shapes.logger],
			maxHints: 40,
		});
		filesScanned += scan.filesScanned;
		linesAdded += scan.linesAdded;
		prints += shapes.print.reduce((sum, [label]) => sum + countLabel(scan, label), 0);
		loggers += shapes.logger.reduce((sum, [label]) => sum + countLabel(scan, label), 0);
		for (const hint of scan.hints) {
			const isPrint = shapes.print.some(([label]) => label === hint.pattern);
			hints.push({
				...hint,
				pattern: `${language}:${hint.pattern}`,
				flags: {
					...hint.flags,
					kind: isPrint ? "print" : "logger",
					toolPath: TOOL_PATH.test(hint.file),
				},
			});
		}
	}
	const listed = hints.slice(0, 40);
	const printsInToolPaths = listed.filter(
		(h) => h.flags.kind === "print" && h.flags.toolPath === true,
	).length;
	// Whether a bounded lexical search of the checkout matches a logger definition, import or native call.
	const existing = await grep(
		String.raw`\bLogger\s*\(|\bos_log|\bNSLogv?\s*\(|import android\.util\.Log\b|\bTimber\b|LoggerFactory|import logging|from 'pino'|from "pino"|winston`,
		repoPath,
		{ maxResults: 5 },
	);
	const directions: string[] =
		prints + loggers > listed.length
			? [
					`${String(prints + loggers)} diagnostic line(s) added; ${String(listed.length)} are listed. The counts by kind cover every line; the tool-path count covers only the listed rows.`,
				]
			: [];
	if (prints > 0) {
		directions.push(
			`${prints} print-style call(s) added (${printsInToolPaths} listed under a tool or script path) against ${loggers} logger call(s); ${existing.length > 0 ? `the checkout matches a logger (${existing[0]?.file ?? ""})` : "a bounded search of the checkout matched no logger definition, which does not show there is none"}. Read each print's file to decide whether it is the program's output, a DEBUG-only block or a shipped diagnostic.`,
		);
	} else if (loggers > 0) {
		directions.push(`${loggers} logger call(s) added and no print-style call.`);
	}
	return {
		hints: listed,
		metrics: {
			printsAdded: prints,
			loggerCallsAdded: loggers,
			printsInToolPaths,
			checkoutHasLogger: existing.length > 0 ? 1 : 0,
			filesScanned,
			linesAdded,
		},
		directions,
	};
}

// Precompute HINTS for handles-errors-instead-of-swallowing-them: locate error-discarding / swallowing
// constructs in ADDED code, across languages. CANDIDATES only — the LLM decides whether the error is
// genuinely swallowed (no surfacing, logging, or recovery). Empty/no-op catch bodies routinely span lines
// (`catch {\n}`), so patterns run over a window of CONSECUTIVE added lines per file, NOT a single line.
// General by design: a per-language pattern table keyed off the file extension. Adding a language = a row.
import { isCommentLine } from "../lib/declarations.ts";
import { languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// language key -> [human label, regex] of error-discarding / swallowing constructs in ADDED code. The `\s`
// in each regex spans the newlines joined into a window, so multi-line empty bodies match.
const LANG_PATTERNS: Record<string, [string, RegExp][]> = {
	swift: [
		["try? (discards error)", /\btry\?\s/u],
		["empty catch", /\bcatch\s*\{\s*\}/u],
		["catch with only print", /\bcatch\s*\{\s*print\s*\([^)]*\)\s*\}/u],
		["error ignored: if let error {}", /\bif\s+let\s+error\b[^{]*\{\s*\}/u],
		// Constructs the criteria ask to classify, not swallows in themselves: a fallback on a failable
		// conversion and a bare early return are where a failure is most often dropped quietly.
		[
			"?? fallback on a failable conversion",
			/\b(?:Int|Double|Float|Decimal|Bool|URL|UUID)\s*\([^)]*\)\s*\?\?/u,
		],
		["guard … else { return }", /\bguard\b[^{]*\belse\s*\{\s*return\s*\}/u],
	],
	typescript: [
		["empty catch", /\bcatch\s*(?:\([^)]*\))?\s*\{\s*\}/u],
		[".catch(noop)", /\.catch\s*\(\s*\(\s*[^)]*\)\s*=>\s*\{\s*\}\s*\)/u],
		[
			"catch with only console",
			/\bcatch\s*(?:\([^)]*\))?\s*\{\s*console\.[a-z]+\([^)]*\)\s*;?\s*\}/u,
		],
	],
	javascript: [
		["empty catch", /\bcatch\s*(?:\([^)]*\))?\s*\{\s*\}/u],
		[".catch(noop)", /\.catch\s*\(\s*\(\s*[^)]*\)\s*=>\s*\{\s*\}\s*\)/u],
		[
			"catch with only console",
			/\bcatch\s*(?:\([^)]*\))?\s*\{\s*console\.[a-z]+\([^)]*\)\s*;?\s*\}/u,
		],
	],
	python: [
		["except: pass", /\bexcept[^:]*:\s*pass\b/u],
		["bare except", /^\s*except\s*:/mu],
		["except ...: continue", /\bexcept[^:]*:\s*continue\b/u],
	],
	go: [
		[
			"blank-identifier assignment (possible ignored error)",
			/\b_\s*(?:,\s*[a-zA-Z0-9_]+)?\s*:?=\s*[a-zA-Z_][a-zA-Z0-9_.]*\s*\(/u,
		],
		["empty if err != nil", /\bif\s+err\s*!=\s*nil\s*\{\s*\}/u],
	],
	java: [
		["empty catch", /\bcatch\s*\([^)]*\)\s*\{\s*\}/u],
		[
			"catch printStackTrace only",
			/\bcatch\s*\([^)]*\)\s*\{\s*[a-zA-Z0-9_.]*\.printStackTrace\s*\(\s*\)\s*;?\s*\}/u,
		],
	],
	kotlin: [
		["empty catch", /\bcatch\s*\([^)]*\)\s*\{\s*\}/u],
		["runCatching{}.getOrNull", /runCatching\s*\{[\s\S]*?\}\s*\.getOrNull\s*\(\s*\)/u],
	],
	rust: [
		[".ok(); (discards Err)", /\.ok\s*\(\s*\)\s*;/u],
		["let _ = call()", /\blet\s+_\s*=\s*[a-zA-Z_][a-zA-Z0-9_.:]*\s*\(/u],
		["if let Err(_) {} empty", /\bif\s+let\s+Err\s*\(\s*_\s*\)[^{]*\{\s*\}/u],
	],
	ruby: [
		["rescue => e (unused)", /\brescue\s*=>\s*[a-z_]+\s*$/mu],
		["rescue; end", /\brescue\b[^;\n]*;\s*end\b/u],
	],
};

// Group a file's added lines into windows of CONSECUTIVE line numbers so a multi-line construct
// (e.g. `catch {` then `}`) is one searchable text block without falsely joining distant additions.
function consecutiveWindows(added: Map<number, string>): { start: number; lines: string[] }[] {
	const windows: { start: number; lines: string[] }[] = [];
	// The open window carries its own first and last line number, so "is there a window" and "what does
	// it end at" are one nullable value rather than length checks against a scratch array.
	let open: { start: number; end: number; lines: string[] } | null = null;
	for (const n of [...added.keys()].toSorted((a, b) => a - b)) {
		if (open !== null && n !== open.end + 1) {
			windows.push({ start: open.start, lines: open.lines });
			open = null;
		}
		open ??= { start: n, end: n, lines: [] };
		open.end = n;
		open.lines.push(added.get(n) ?? "");
	}
	if (open !== null) {
		windows.push({ start: open.start, lines: open.lines });
	}
	return windows;
}

export default function handlesErrorsInsteadOfSwallowingThem(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byLang: Record<string, number> = {};
	let filesScanned = 0;
	let linesAdded = 0;
	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		if (lang === null) {
			continue;
		}
		const patterns = LANG_PATTERNS[lang];
		if (!patterns) {
			continue;
		}
		filesScanned += 1;
		linesAdded += df.addedLines.size;
		for (const w of consecutiveWindows(df.addedLines)) {
			const text = w.lines.join("\n");
			for (const [name, re] of patterns) {
				const match = text.match(re);
				if (!match || match.index === undefined) {
					continue;
				}
				const offset = text.slice(0, match.index).split("\n").length - 1;
				const lineNum = w.start + offset;
				const lineContent = w.lines[offset] ?? "";
				if (isCommentLine(lineContent, lang)) {
					continue;
				}
				hints.push({
					file: path,
					line: lineNum,
					pattern: `${lang}:${name}`,
					context: lineContent.trim().slice(0, 160),
					inDiff: true,
					flags: {},
				});
				byLang[lang] = (byLang[lang] ?? 0) + 1;
				// one hint per window — the LLM reads the full diff for the rest
				break;
			}
		}
	}
	const directions =
		hints.length > 0
			? [
					`Found ${hints.length} possible error-discard constructs in ${Object.keys(byLang).length} languages. First establish whether each call can fail. For each failure, inspect whether it stays visible. A valid fixed URL has no runtime-dependent parse failure. A later empty-value check does not swallow an error already recorded by its handler.`,
				]
			: [];
	return {
		hints: hints.slice(0, 40),
		metrics: { errorSwallowCandidates: hints.length, filesScanned, linesAdded, ...byLang },
		directions,
	};
}

// Precompute FACTS for validates-inputs-and-edge-cases-at-the-boundary: the added lines of source code
// that hold a construct which can fail or mislead on an edge value — a subscript or slice, a division by
// a name, a parse the language does not force the author to handle, an extreme sentinel, a payload
// decode, a request's own input — across languages. A row marks where a consuming site may be, never an
// observation: whether its value comes from outside the local logic, and what already handles its bad case,
// is read from the code, and the criteria decide. String-literal text and comments are not scanned; a
// lookup or parse whose result the language makes optional is not listed, and a crash operator the author
// wrote (`!`, `try!`, `unwrap()`) is the crash practice's. Adding a language = adding a row.
import { codeLines, isCommentLine } from "../lib/declarations.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const COMMON: [string, RegExp][] = [
	// `items[i]`, `cast[0..<2]`; not a lookup already made safe (`dict[k] ?? d`, `[k, default: 0]`,
	// `ns[k] as? T`) nor an assignment target.
	[
		"subscript or slice",
		/[A-Za-z0-9_)\]]\[(?![^\]]*\bdefault:)[^\]]+\](?!\s*(?:\?\?|as\?|=(?!=)))/u,
	],
	// A divisor that is a name or a call; a literal divisor cannot be zero.
	["division or remainder by a name", /[A-Za-z0-9_)\]]\s*[/%](?![/*=])\s*[A-Za-z_(]/u],
	// The seed of a minimum, a maximum or a fallback that can reach output unchanged.
	[
		"extreme sentinel",
		/\b(?:U?Int\d*|Double|Float|CGFloat)\.(?:max|min|infinity|greatestFiniteMagnitude)\b|\b(?:Integer|Long|Double|Float)\.(?:MAX|MIN)_VALUE\b|\bNumber\.(?:MAX|MIN)_(?:SAFE_INTEGER|VALUE)\b|\bsys\.maxsize\b|\bmath\.inf\b/u,
	],
];

// language key -> [label, regex] of edge constructs in added code, beside COMMON.
const LANG_PATTERNS: Record<string, [string, RegExp][]> = {
	// `Int(text)`, `Double(s)`, `.first`, `dict[key]` return Optionals the compiler makes the author handle.
	swift: [["payload decode", /(?<![Cc]ontainer)\.decode\s*\(/u]],
	typescript: [
		["parseInt/parseFloat", /\bparse(?:Int|Float)\s*\(/u],
		["Number(...) parse", /\bNumber\s*\(/u],
		["JSON.parse", /\bJSON\.parse\s*\(/u],
	],
	javascript: [
		["parseInt/parseFloat", /\bparse(?:Int|Float)\s*\(/u],
		["Number(...) parse", /\bNumber\s*\(/u],
		["JSON.parse", /\bJSON\.parse\s*\(/u],
	],
	python: [
		["int()/float() parse", /\b(?:int|float)\s*\(/u],
		["json.loads", /\bjson\.loads\s*\(/u],
		[".pop()", /\.pop\s*\(/u],
		["next(...)", /\bnext\s*\(/u],
	],
	go: [
		["strconv parse", /\bstrconv\.(?:Atoi|Parse[A-Za-z]+)\s*\(/u],
		["json.Unmarshal", /\bjson\.Unmarshal\s*\(/u],
	],
	java: [
		[".get(i) access", /\.get\s*\(\s*[A-Za-z_]/u],
		["Integer/Long/Double.parse", /\b(?:Integer|Long|Double|Float)\.parse[A-Za-z]+\s*\(/u],
		["valueOf parse", /\b(?:Integer|Long|Double|Float)\.valueOf\s*\(/u],
		[".charAt/.substring", /\.(?:charAt|substring)\s*\(/u],
	],
	kotlin: [
		["toInt/toDouble parse", /\.to(?:Int|Long|Double|Float)\s*\(\s*\)/u],
		[".first()/.last()", /\.(?:first|last)\s*\(\s*\)/u],
	],
	rust: [],
	ruby: [
		["JSON.parse", /\bJSON\.parse\s*\(/u],
		[".fetch", /\.fetch\s*\(/u],
	],
	c: [
		["atoi/strtol parse", /\b(?:atoi|atol|atof|strtol|strtod)\s*\(/u],
		["pointer deref *", /(?:^|[^\w)])\*[A-Za-z_]/u],
	],
	csharp: [
		[
			"int.Parse/Convert",
			/\b(?:int|long|double|float|decimal|Int32|Int64|Convert)\.(?:Parse|To[A-Za-z]+)\s*\(/u,
		],
		["JsonSerializer.Deserialize", /\.Deserialize\s*\(/u],
		[".First()/.Last()/.Single()", /\.(?:First|Last|Single)\s*\(\s*\)/u],
	],
};

// Where a request's own input enters a handler: the criteria's "a request param, body or header".
const REQUEST_INPUT: Record<string, RegExp> = {
	java: /@(?:RequestParam|PathVariable|RequestBody|RequestHeader)\b/u,
	kotlin: /@(?:RequestParam|PathVariable|RequestBody|RequestHeader)\b/u,
	typescript: /\breq(?:uest)?\.(?:params|query|body|headers)\b/u,
	javascript: /\breq(?:uest)?\.(?:params|query|body|headers)\b/u,
	python: /\brequest\.(?:args|form|json|GET|POST|query_params|data)\b/u,
	go: /\br\.(?:URL\.Query|FormValue|PostFormValue|PathValue)\b/u,
	swift: /\breq\.(?:parameters|query|content)\b/u,
};

export default function validatesInputsAndEdgeCasesAtTheBoundary(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byKind: Record<string, number> = {};
	let filesScanned = 0;
	let linesScanned = 0;

	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		const own = lang === null ? undefined : LANG_PATTERNS[lang];
		// A test's fixtures are not a boundary.
		if (lang === null || !own || isTestPath(path)) {
			continue;
		}
		const request = REQUEST_INPUT[lang];
		const patterns: [string, RegExp][] =
			request === undefined ? [...COMMON, ...own] : [["request input", request], ...COMMON, ...own];
		const code = codeLines(lang, df.addedLines);
		filesScanned += 1;
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, lang)) {
				continue;
			}
			linesScanned += 1;
			const labels = patterns
				.filter(([, re]) => re.test(code.get(line) ?? ""))
				.map(([name]) => name);
			if (labels.length === 0) {
				continue;
			}
			for (const label of labels) {
				byKind[label] = (byKind[label] ?? 0) + 1;
			}
			hints.push({
				file: path,
				line,
				pattern: `${lang}:${labels.join(" + ")}`,
				context: content.trim().slice(0, 160),
				inDiff: true,
				flags: {},
			});
		}
	}

	const kinds = Object.entries(byKind)
		.map(([kind, count]) => `${String(count)} ${kind}`)
		.join(", ");
	const directions =
		hints.length > 0
			? [
					`${hints.length} added line(s) hold a construct that can fail or mislead on an edge value (${kinds}). String-literal text, comments and test files were not scanned; lookups and parses whose result the language makes optional, and crash operators, are not listed. A listed line marks where a consuming site may be, not an observation: whether its value comes from outside the local logic, and what already handles its bad case, is read from the code.`,
				]
			: [];

	return {
		hints: hints.slice(0, 40),
		metrics: {
			edgeConstructLines: hints.length,
			filesScanned,
			linesScanned,
			...byKind,
		},
		directions,
	};
}

// Precompute FACTS for avoids-unsafe-panics-and-chosen-crashes: the added lines that spell a crash
// operator the author wrote — a force unwrap, `try!`, a force cast, an abort — across languages, each
// with where it runs: inside a preview block or in a test file. A row matches spelling on one line; it
// does not know the operand's type, where the value came from, or what bounds it, and the criteria
// decide which rows are lapses. Implicit traps (a subscript, an integer division) are the input
// practice's, so they are not listed here. Adding a language = adding a row, no engine change.
import { readFile } from "node:fs/promises";
import nodePath from "node:path";

import { blockExtents, codeLines, isCommentLine } from "../lib/declarations.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// language key -> [label, regex] of crash operators the author writes, matched against the line's code.
const LANG_PATTERNS: Record<string, [string, RegExp][]> = {
	swift: [
		["try!", /\btry!/u],
		["fatalError", /\bfatalError\s*\(/u],
		["force cast as!", /\bas!\s/u],
		[
			"precondition or assert",
			/\b(?:precondition|preconditionFailure|assert|assertionFailure)\s*\(/u,
		],
		["exit or abort", /\b(?:exit|abort)\s*\(/u],
		// `try!` and `as!` have their own rows.
		["force unwrap", /[A-Za-z0-9_)\]](?<!\btry|\bas)!(?:[.\s),\]]|$)/u],
	],
	typescript: [
		["process.exit", /\bprocess\.exit\s*\(/u],
		["non-null assertion", /[A-Za-z0-9_)\]]!(?:[.;)\s,\]]|$)/u],
	],
	javascript: [["process.exit", /\bprocess\.exit\s*\(/u]],
	python: [
		["sys.exit", /\bsys\.exit\s*\(/u],
		["os._exit", /\bos\._exit\s*\(/u],
		["raise SystemExit", /\braise\s+SystemExit\b/u],
		["bare assert in code", /^\s*assert\s+/u],
	],
	go: [
		["panic(", /\bpanic\s*\(/u],
		["log.Fatal", /\blog\.Fatal[a-z]*\s*\(/u],
		["os.Exit", /\bos\.Exit\s*\(/u],
	],
	java: [
		["System.exit", /\bSystem\.exit\s*\(/u],
		["throw AssertionError", /\bthrow\s+new\s+AssertionError\b/u],
		["Optional.get()", /\bOptional[^;]*\.get\s*\(\s*\)/u],
	],
	kotlin: [
		["!! force non-null", /!!(?:[.\s)]|$)/u],
		["error(", /(?:^|[^.\w])error\s*\(/u],
		["TODO(", /\bTODO\s*\(/u],
	],
	rust: [
		[".unwrap()", /\.unwrap\s*\(\s*\)/u],
		[".expect(", /\.expect\s*\(/u],
		["panic!", /\bpanic!\s*\(/u],
		["unreachable!", /\bunreachable!\s*\(/u],
		["unimplemented!/todo!", /\b(?:unimplemented|todo)!\s*\(/u],
	],
	ruby: [
		["exit!", /\bexit!/u],
		["abort", /\babort\b/u],
	],
	c: [
		["abort(", /\babort\s*\(/u],
		["exit(", /\bexit\s*\(/u],
		["assert(", /\bassert\s*\(/u],
	],
	// Objective-C is C with Cocoa's assertion macros, not Swift: no bang operators to find.
	"objective-c": [
		["abort(", /\babort\s*\(/u],
		["exit(", /\bexit\s*\(/u],
		["NSAssert", /\bNS(?:C)?Assert\s*\(/u],
	],
	csharp: [
		["Environment.Exit", /\bEnvironment\.Exit\s*\(/u],
		["Environment.FailFast", /\bEnvironment\.FailFast\s*\(/u],
		["Debug.Assert", /\bDebug\.Assert\s*\(/u],
		["null-forgiving !", /[A-Za-z0-9_)\]]!\.(?=[A-Za-z_])/u],
	],
};

// Code that runs only when Xcode renders a preview, never on a user's device.
const PREVIEW_OPENER = /^\s*(?:#Preview\b|(?:\w+\s+)*struct\s+\w+\s*:\s*PreviewProvider\b)/u;

/** The new side as far as the hunks show it: context and added lines at their numbers, gaps empty. */
function newSideOfHunks(file: DiffFile): string {
	const lines: string[] = [];
	for (const hunk of file.hunks) {
		let number = hunk.newStart;
		for (const line of hunk.lines) {
			if (line.startsWith("-")) {
				continue;
			}
			while (lines.length < number - 1) {
				lines.push("");
			}
			lines[number - 1] = line.slice(1);
			number += 1;
		}
	}
	return lines.join("\n");
}

/** The lines inside a preview block: read from the pinned file, else from what the hunks show. */
async function previewLines(
	repoPath: string,
	file: DiffFile,
	language: string,
): Promise<Set<number>> {
	let source: string;
	try {
		source = await readFile(nodePath.join(repoPath, file.path), "utf8");
	} catch {
		source = newSideOfHunks(file);
	}
	const lines = new Set<number>();
	for (const { start, end } of blockExtents(language, source, PREVIEW_OPENER) ?? []) {
		for (let line = start; line <= end; line += 1) {
			lines.add(line);
		}
	}
	return lines;
}

export default async function avoidsUnsafePanicsAndChosenCrashes(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byKind: Record<string, number> = {};
	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		const patterns = lang === null ? undefined : LANG_PATTERNS[lang];
		if (lang === null || !patterns) {
			continue;
		}
		const code = codeLines(lang, df.addedLines);
		const preview = lang === "swift" ? await previewLines(repoPath, df, lang) : new Set<number>();
		const testFile = isTestPath(path);
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, lang)) {
				continue;
			}
			const labels = patterns
				.filter(([, re]) => re.test(code.get(line) ?? ""))
				.map(([name]) => name);
			if (labels.length === 0) {
				continue;
			}
			for (const label of labels) {
				byKind[label] = (byKind[label] ?? 0) + 1;
			}
			hints.push({
				file: path,
				line,
				pattern: `${lang}:${labels.join(" + ")}`,
				context: content.trim().slice(0, 160),
				inDiff: true,
				flags: { inPreview: preview.has(line), testFile },
			});
		}
	}
	// Rows on an ordinary path first, so preview and test rows cannot push them out of a shown sample.
	hints.sort(
		(a, b) =>
			Number(a.flags.inPreview === true || a.flags.testFile === true) -
			Number(b.flags.inPreview === true || b.flags.testFile === true),
	);
	const inPreview = hints.filter((h) => h.flags.inPreview === true).length;
	const inTests = hints.filter((h) => h.flags.testFile === true).length;
	const kinds = Object.entries(byKind)
		.map(([kind, count]) => `${String(count)} ${kind}`)
		.join(", ");
	const directions =
		hints.length > 0
			? [
					`${hints.length} added line(s) spell a crash operator (${kinds}); ${inPreview} sit inside a preview block and ${inTests} in test files. String-literal text and comments were not scanned. A row matches spelling on one line: it does not know the operand's type, where the value came from, or what bounds it.`,
				]
			: [];
	return {
		hints: hints.slice(0, 40),
		metrics: { crashOperatorLines: hints.length, inPreview, inTests, ...byKind },
		directions,
	};
}

// Precompute HINTS for validates-and-escapes-untrusted-input: surface ADDED lines where an untrusted-INPUT
// token (a SOURCE) and a dangerous OPERATION token (a SINK) co-occur in the same file within a small line
// window — i.e. the taint flow a reviewer is most likely to miss by eye. CANDIDATES only: the LLM traces
// whether the source actually reaches the sink unvalidated/unescaped and decides. General by design: a
// per-language SOURCE table + a SINK table keyed off the file extension. Adding a language = adding rows,
// no engine change. The taint flow spans lines, so we pair each source to nearby sinks and hand the LLM
// the exact span to trace.
import { isCommentLine } from "../lib/declarations.ts";
import { languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/** A label -> pattern table row. The label is what a hint reports, so it is rendered verbatim. */
type PatternRows = [string, RegExp][];

/**
 * `all` is checked for every file whatever its language; `byLanguage` refines it for the languages
 * that have their own surfaces. Splitting the two apart makes "there are always cross-language rows"
 * a fact the type carries, instead of one key of a string-indexed record that reads as optional.
 */
interface PatternTable {
	all: PatternRows;
	byLanguage: Record<string, PatternRows>;
}

// Sources of untrusted input (request/CLI/env/file/stdin). Cross-language patterns live under "all" and are
// checked for every file; language-specific rows refine the common web/runtime surfaces.
const SOURCES: PatternTable = {
	all: [
		["request/req param", /\b(?:request|req)\b\s*[.[]/iu],
		[
			"params/query/body/headers/cookies",
			/\b(?:params|query|queryString|body|headers|cookies)\b\s*[.[]/u,
		],
		["env var", /\b(?:process\.env|os\.environ|System\.getenv|getenv|std::env::var|ENV)\b/u],
		[
			"argv / CLI args",
			/\b(?:argv|sys\.args|os\.Args|process\.argv|CommandLine\.arguments|args\[)\b/u,
		],
		["stdin / scanner read", /\b(?:stdin|readLine|Scanner|BufferedReader|input\s*\(|gets\b)\b/u],
	],
	byLanguage: {
		java: [
			[
				"servlet getParameter/getHeader",
				/\.get(?:Parameter|Header|QueryString|Cookies|InputStream|Reader)\s*\(/u,
			],
			[
				"@RequestParam/@PathVariable/@RequestBody",
				/@(?:RequestParam|PathVariable|RequestBody|RequestHeader|CookieValue)\b/u,
			],
			[
				"file read",
				/\bnew\s+(?:FileReader|FileInputStream)\s*\(|Files\.(?:read|newInputStream)\b/u,
			],
		],
		typescript: [
			["express/koa req", /\breq\.(?:params|query|body|headers|cookies|get)\b/u],
			["fs read", /\bfs\.(?:readFile|readFileSync|createReadStream)\b/u],
			["URL/searchParams", /\b(?:searchParams|URLSearchParams|location\.(?:search|hash|href))\b/u],
		],
		python: [
			[
				"flask/django request",
				/\brequest\.(?:args|form|values|json|GET|POST|data|files|headers|cookies)\b/u,
			],
			["open() read", /\bopen\s*\([^)]*['"]r/u],
		],
		go: [
			["http.Request fields", /\br\.(?:URL|Form|PostForm|Body|Header|Cookie)\b/u],
			["FormValue/Query", /\.(?:FormValue|Query|PathValue)\s*\(/u],
		],
		ruby: [["rails params", /\bparams\[/u]],
		php: [["superglobals", /\$_(?:GET|POST|REQUEST|COOKIE|SERVER|FILES)\b/u]],
		csharp: [["Request fields", /\bRequest\.(?:Query|Form|Headers|Cookies|Body|QueryString)\b/u]],
		swift: [
			["URLSession / response data", /\bURLSession\b|\.dataTask\b|\bdata\s*\(\s*for\s*:/u],
			[
				"request header / URL component",
				/\.value\s*\(\s*forHTTPHeaderField|\bURLComponents\b|\.queryItems\b/u,
			],
			[
				"UserDefaults / FileManager / env",
				/\b(?:UserDefaults\.standard|FileManager\.default|ProcessInfo\.processInfo\.environment)\b/u,
			],
		],
	},
};

// Sinks: dangerous operations that must receive validated/escaped input (SQL, command/eval, markup, path,
// templating, deserialization). Cross-language rows under "all"; language rows refine.
const SINKS: PatternTable = {
	all: [
		[
			"raw SQL string-concat",
			/\b(?:SELECT|INSERT|UPDATE|DELETE|WHERE|FROM)\b[^;]*(?:\+|\$\{|%s|f["']|`|\|\||\.\.)/iu,
		],
		["eval", /\beval\s*\(/u],
		[
			"exec / shell",
			/\b(?:exec|execSync|execve|spawn|popen|os\.system|subprocess\.(?:call|run|Popen)|shell_exec)\s*\(|(?<![.\w])system\s*\(/u,
		],
		[
			"deserialize",
			/\b(?:pickle\.loads|yaml\.load\b|Marshal\.load|unserialize|JSON\.parse|deserialize)\s*\(/iu,
		],
		// A render call, not the word: SwiftUI's `.renderingMode(.template)` is a native image mode, and
		// `Handlebars.compile(` or `jinja2.Template(` only builds a template that a later call renders.
		[
			"template render",
			/\b(?:render(?:_template(?:_string)?)?|Mustache\.render|ejs\.render)\s*\(/u,
		],
		[
			"path join with input",
			/\b(?:path\.join|os\.path\.join|filepath\.Join|Paths\.get|File\s*\()/u,
		],
	],
	byLanguage: {
		java: [
			["Runtime.exec / ProcessBuilder", /\b(?:Runtime\.getRuntime\(\)\.exec|ProcessBuilder)\b/u],
			[
				"Statement.execute (no prepare)",
				/\b(?:createStatement|Statement)\b[^;]*\.(?:execute|executeQuery|executeUpdate)\b/u,
			],
			["ObjectInputStream", /\bObjectInputStream\b/u],
		],
		typescript: [
			[
				"innerHTML / dangerouslySetInnerHTML",
				/\b(?:innerHTML|outerHTML|dangerouslySetInnerHTML|insertAdjacentHTML|document\.write)\b/u,
			],
			["new Function", /\bnew\s+Function\s*\(/u],
		],
		python: [
			["cursor.execute concat", /\bcursor\.execute\b/u],
			["os.system / subprocess shell=True", /shell\s*=\s*True/u],
		],
		php: [["echo/print to HTML", /\b(?:echo|print)\b/u]],
		csharp: [
			["SqlCommand concat", /\bnew\s+SqlCommand\b/u],
			["Html.Raw", /\bHtml\.Raw\s*\(/u],
		],
		swift: [
			[
				"WKWebView loadHTMLString / evaluateJavaScript",
				/\b(?:loadHTMLString|evaluateJavaScript)\s*\(/u,
			],
			["sqlite3 exec/prepare", /\bsqlite3_(?:exec|prepare(?:_v2)?)\s*\(/u],
			["Process / shell launch", /\bProcess\s*\(\)|\.launchPath\b|\blaunch\s*\(\)/u],
			["NSExpression / String(format:)", /\bNSExpression\b|\bString\s*\(\s*format\s*:/u],
		],
	},
};

// Sources and sinks co-occurring within this many added lines are surfaced as a candidate flow.
const WINDOW = 25;

/** JavaScript shares TypeScript's surfaces; the lib names the two apart. */
function rowsLanguage(lang: string | null): string | null {
	return lang === "javascript" ? "typescript" : lang;
}

/** Cross-language rows first, then the rows for this file's language (none when it is unrecognised). */
function rowsFor(table: PatternTable, lang: string | null): PatternRows {
	return [...table.all, ...(lang === null ? [] : (table.byLanguage[lang] ?? []))];
}

function firstMatch(rows: PatternRows, content: string): string | null {
	for (const [label, re] of rows) {
		if (re.test(content)) {
			return label;
		}
	}
	return null;
}

export default function validatesAndEscapesUntrustedInput(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	let flowCount = 0;
	let linesAdded = 0;

	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		const sourceRows = rowsFor(SOURCES, rowsLanguage(lang));
		const sinkRows = rowsFor(SINKS, rowsLanguage(lang));

		// Collect source / sink positions on ADDED lines only.
		const srcLines: { line: number; label: string; content: string }[] = [];
		const sinkLines: { line: number; label: string; content: string }[] = [];
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, lang ?? "")) {
				continue;
			}
			linesAdded += 1;
			const s = firstMatch(sourceRows, content);
			if (s !== null) {
				srcLines.push({ line, label: s, content });
			}
			const k = firstMatch(sinkRows, content);
			if (k !== null) {
				sinkLines.push({ line, label: k, content });
			}
		}
		if (srcLines.length === 0 || sinkLines.length === 0) {
			continue;
		}

		// Surface each sink that has a source within WINDOW lines — that pairing is the flow to trace.
		for (const sink of sinkLines) {
			const near = srcLines.find((s) => Math.abs(s.line - sink.line) <= WINDOW);
			if (!near) {
				continue;
			}
			flowCount += 1;
			hints.push({
				file: path,
				line: sink.line,
				pattern: `source→sink: ${near.label} → ${sink.label}`,
				context: sink.content.trim().slice(0, 160),
				inDiff: true,
				flags: {
					sourceLine: near.line,
					sourceToken: near.label,
					sinkToken: sink.label,
					lineDistance: Math.abs(near.line - sink.line),
				},
			});
		}
	}

	const directions =
		flowCount > 0
			? [
					`Found ${flowCount} added line(s) where an untrusted-input source (request/params/env/file/stdin/argv) and a dangerous sink (raw SQL concat, exec/eval/system, innerHTML, path join, template render, deserialize) co-occur within ${WINDOW} lines — trace whether the source reaches the sink without validation/escaping/parameterization, and confirm before deciding.`,
				]
			: [];

	return {
		hints: hints.slice(0, 40),
		metrics: { sourceSinkFlows: flowCount, filesScanned: diffFiles.size, linesAdded },
		directions,
	};
}

// Precompute HINTS for avoids-insecure-defaults-and-over-broad-permissions: locate insecure-default /
// over-broad-permission / secret-exposure constructs ADDED in the diff, across languages. CANDIDATES only —
// the LLM confirms whether each is a real, exploitable insecure default on a reachable path. General by
// design: a pattern table keyed off the construct, applied to every added code line regardless of language.
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// [label, regex] — each fires on an ADDED line. Tuned to the auth/transport/secret surface a login or API
// change touches, where a "looks fine" review most often misses the real insecure default.
const PATTERNS: [string, RegExp][] = [
	// A credential-named value interpolated into a URL path or query. Matches
	// ${...}/#{...} (JS/Ruby/Kotlin) and Swift's \(...) interpolation of a credential-named variable into a path.
	[
		"credential-named value in URL path/query",
		/["'`](?:https?:\/\/|\/)[^"'`\n]*(?:\\\(|[$#]\{)[^"'`\n)}]*\b(?:token|secret|password|api[_-]?key|auth|session|refresh)\w*/iu,
	],
	// Keychain write — an omitted kSecAttrAccessible defaults to WhenUnlocked; whether the effective class,
	// synchronization and backup migration fit the stored secret is the review's.
	["keychain write", /\bSecItemAdd\b|kSecValueData\b/u],
	// Logging a credential-named value or response body to console/log.
	[
		"logs credential-named value / response body",
		/\b(?:print|NSLog|console\.(?:log|debug|info)|System\.out\.print\w*|log\.(?:debug|info|warn))\s*\([^)]*\b(?:token|password|secret|credential|response|body|account)\b/iu,
	],
	// Insecure transport / disabled TLS verification.
	[
		"insecure transport / TLS off",
		/NSAllowsArbitraryLoads|allowsArbitraryLoads|rejectUnauthorized\s*:\s*false|InsecureSkipVerify\s*:\s*true|verify\s*=\s*False|\.insecure\(\)|http:\/\/(?!localhost|127\.0\.0\.1|0\.0\.0\.0)/u,
	],
	// Over-broad permissions / wildcard access.
	[
		"over-broad permission / wildcard",
		/chmod\s+0?777|\b0o?777\b|permitAll\(\)|\.anyRequest\(\)\.permitAll|Access-Control-Allow-Origin["'\s:]*\*|allowedOrigins?["'\s:]*\*/u,
	],
	// A literal assigned to a credential-named field.
	[
		"credential-named literal",
		/\b(?:password|secret|api[_-]?key|token)\s*[:=]\s*["'`][A-Za-z0-9_\-/+]{8,}["'`]/iu,
	],
];

function isComment(t: string): boolean {
	return t.startsWith("//") || t.startsWith("#") || t.startsWith("*") || t.startsWith("/*");
}

export default function avoidsInsecureDefaultsAndOverBroadPermissions(
	_repo: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const byKind: Record<string, number> = {};
	for (const [path, df] of diffFiles) {
		for (const [line, content] of df.addedLines) {
			const trimmed = content.trimStart();
			if (isComment(trimmed)) {
				continue;
			}
			for (const [label, re] of PATTERNS) {
				if (re.test(content)) {
					hints.push({
						file: path,
						line,
						pattern: label,
						context: content.trim().slice(0, 160),
						inDiff: true,
						flags: {},
					});
					byKind[label] = (byKind[label] ?? 0) + 1;
					break;
				}
			}
		}
	}
	const directions =
		hints.length > 0
			? [
					`Found ${hints.length} insecure-default / secret-exposure candidate(s) on added lines — investigate each on the reachable auth/transport surface: for credential-named URL, literal and logging leads, establish the value’s role under class 5 of the standard before deciding whether it exposes credential material; a keychain write takes its accessibility from kSecAttrAccessible, WhenUnlocked when omitted, which is not a defect by itself; disabled TLS / wildcard CORS / world-writable perms are over-broad. Confirm whether each is real and exploitable before deciding.`,
				]
			: [];
	return {
		hints: hints.slice(0, 40),
		metrics: { insecureDefaultCandidates: hints.length, ...byKind },
		directions,
	};
}

// Precompute HINTS for changes-dependencies-deliberately. Surfaces candidates only — the LLM judges whether a
// dependency edit was deliberate (intentional add/remove/bump with an appropriate constraint) or careless
// (loosened pin, dropped version, no lockfile). General by design: a per-manifest pattern table keyed off
// the file basename, NOT a single ecosystem. Adding an ecosystem = adding a row, no engine change.
//
// The table reads changed lines, not manifest sections, so a match is a CANDIDATE dependency line: a
// package.json `engines` entry or a Cargo `[package]` `rust-version` has a dependency line's shape too, and
// only the section around it says which it is. We pair an added line against a removed line for the SAME
// name and label the constraint delta between the two lines:
//   ONLY_ADDED    — the name matches only on a + line (new, or moved or reformatted from outside the diff)
//   ONLY_REMOVED  — the name matches only on a - line (dropped, or moved or reformatted)
//   PIN_LOOSENED  — exact/narrower constraint became a range/caret/tilde (==1.2.3 -> >=1.2, 1.2.3 -> ^1.2.3)
//   PIN_DROPPED   — a version constraint was present and is now entirely absent
//   BUMPED        — same constraint shape, different version value
// Manifests that spread one dependency over several lines (Maven, XcodeGen) get no such label; their changed
// dependency lines are surfaced as raw leads.
import { globFilesSync } from "../lib/files.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// ecosystem key -> how to recognise its manifest + lockfile, and how to read a "name => constraint" line.
interface Ecosystem {
	// manifest basename test (lowercased)
	isManifest: (base: string) => boolean;
	// lockfile basenames this ecosystem writes
	lockfiles: string[];
	// extract { name, constraint } from a single manifest line, or null if it lacks a dependency line's shape.
	parse: (line: string) => { name: string; constraint: string } | null;
	// For a manifest that spreads one dependency over several lines: the changed lines to surface raw,
	// in place of parse().
	dependencyLine?: RegExp;
}

// A constraint is "loose" if it admits more than one version: range operators, caret, tilde, wildcard, or empty.
const LOOSE = /(?:^$|[\^~*]|>=|<=|>|<|\.x\b|\bx\b|\|\||\s-\s|,)/u;
// A constraint is "exact" if it pins a single version: leading ==, =, or a bare semver-ish token.
const EXACT = /^(?:==?|v)?\d/u;

function isLoose(c: string): boolean {
	const t = c.trim();
	if (t === "" || t === "*") {
		return true;
	}
	if (EXACT.test(t) && !LOOSE.test(t.replace(/^==?/u, ""))) {
		return false;
	}
	return LOOSE.test(t);
}

// A package.json string value LOOKS like a dependency constraint (semver/range/protocol) rather than a
// script body, an `engines`/`exports`/`resolutions`/`config` value, etc. The per-line JSON parser cannot
// see which object block a line sits in, so this shape guard keeps `"build": "tsc"` or `"./dist": "..."`
// out of the dependency tally. A bare "*"/"x"/"latest" and the npm pseudo-protocols (workspace:/npm:/
// file:/link:/git/http) are real dependency specifiers and are admitted.
const VERSIONISH =
	/^(?:[\^~>=<* v]|\d|x\b|latest$|workspace:|npm:|file:|link:|git[+:]|https?:|github:|gitlab:|bitbucket:)/iu;
function isVersionish(c: string): boolean {
	return VERSIONISH.test(c.trim());
}

// --- per-ecosystem line parsers (kept deliberately small + tolerant; the LLM reads full context) ---

// JSON "name": "constraint"  (package.json dependency blocks)
const reJsonDep = /^\s*"(?<name>[^"]+)"\s*:\s*"(?<constraint>[^"]*)"\s*,?\s*$/u;
// Well-known package.json scalar keys that are NOT dependencies — skip so we don't emit a "dep" hint for the
// package's own name/version/etc. Generic to npm manifests, not repo-specific.
const NPM_NON_DEP_KEYS = new Set([
	"name",
	"version",
	"description",
	"license",
	"main",
	"module",
	"type",
	"types",
	"typings",
	"homepage",
	"author",
	"private",
	"packagemanager",
	"bin",
]);
// TOML name = "constraint"  or  name = { version = "constraint" }
const reTomlDep =
	/^\s*(?<name>[A-Za-z0-9_.-]+)\s*=\s*(?:"(?<quoted>[^"]*)"|\{[^}]*version\s*=\s*"(?<table>[^"]*)"[^}]*\})/u;
// requirements.txt  name==1.2.3 / name>=1,<2 / name
const reReqDep = /^\s*(?<name>[A-Za-z0-9_.\-[\]]+)\s*(?<constraint>(?:[<>=!~]=?|@)\S.*)?$/u;
// Gemfile  gem "name", "~> 1.2"
const reGemDep = /^\s*gem\s+["'](?<name>[^"']+)["']\s*(?:,\s*["'](?<constraint>[^"']*)["'])?/u;
// Gradle  implementation("group:name:1.2.3")  or  implementation 'group:name:1.2.3'
const reGradleDep = /["'](?<coordinate>[\w.-]+:[\w.-]+):(?<constraint>[^"']*)["']/u;
// Swift PM  .package(url: "...", from: "1.2.3") / exact: "1.2.3" / "1.0.0"..."2.0.0"
const reSwiftPkg =
	/\.package\(\s*url:\s*["'](?<url>[^"']+)["'][^)]*?(?:from:\s*["'](?<from>[^"']+)["']|exact:\s*["'](?<exact>[^"']+)["']|["'](?<low>[^"']+)["']\s*\.\.[.<]\s*["'](?<high>[^"']+)["'])/u;
// go.mod  require module v1.2.3  (single-line or block-body line)
const reGoMod =
	/^\s*(?:require\s+)?(?<name>[\w./-]+\.[\w./-]+\/\S+|[\w.-]+\/\S+)\s+(?<version>v\d\S*)/u;

/** A Swift PM constraint as one word: `from:`, `exact:`, a range, or nothing when the package pins none. */
function swiftConstraint(
	fromVersion: string | undefined,
	exactVersion: string | undefined,
	rangeLow: string | undefined,
	rangeHigh: string | undefined,
): string {
	if (fromVersion !== undefined && fromVersion !== "") {
		return `from:${fromVersion}`;
	}
	if (exactVersion !== undefined && exactVersion !== "") {
		return `exact:${exactVersion}`;
	}
	if (rangeLow !== undefined && rangeLow !== "" && rangeHigh !== undefined && rangeHigh !== "") {
		return `${rangeLow}..${rangeHigh}`;
	}
	return "";
}

// Cargo.toml and pyproject.toml read dependency lines identically. The two version groups are the two
// arms of an alternation — `name = "1.2"` fills the first, `name = { version = "1.2" }` the second, and
// an inline table with no version key (`name = { features = [...] }`) fills neither.
function parseTomlDependency(line: string): { name: string; constraint: string } | null {
	const [, name, quotedVersion, tableVersion] = reTomlDep.exec(line) ?? [];
	if (name === undefined) {
		return null;
	}
	return { name, constraint: quotedVersion ?? tableVersion ?? "" };
}

const ECOSYSTEMS: Ecosystem[] = [
	{
		isManifest: (b) => b === "package.json",
		lockfiles: ["package-lock.json", "yarn.lock", "pnpm-lock.yaml", "npm-shrinkwrap.json"],
		parse: (line) => {
			// The value group matches empty (`"dep": ""`); the key group cannot, so its absence means the
			// line is not a `"key": "value"` pair at all.
			const [, name, constraint = ""] = reJsonDep.exec(line) ?? [];
			if (name === undefined) {
				return null;
			}
			// Skip the package's own scalar fields (name/version/etc.) so we only surface dependency-block edits.
			if (NPM_NON_DEP_KEYS.has(name.toLowerCase())) {
				return null;
			}
			// Per-line parsing can't tell a dependency block from scripts/engines/exports/resolutions/config —
			// they all share the `"key": "value"` shape. Require the value to look like a version specifier so a
			// `"build": "tsc"` line is not offered as a candidate at all.
			if (!isVersionish(constraint)) {
				return null;
			}
			return { name, constraint };
		},
	},
	{
		// Rust Cargo
		isManifest: (b) => b === "cargo.toml",
		lockfiles: ["Cargo.lock"],
		parse: parseTomlDependency,
	},
	{
		// Python requirements
		isManifest: (b) => b === "requirements.txt" || b.endsWith(".requirements.txt"),
		lockfiles: ["requirements.lock", "Pipfile.lock", "poetry.lock", "uv.lock"],
		parse: (line) => {
			const t = line.trim();
			if (t === "" || t.startsWith("#") || t.startsWith("-")) {
				return null;
			}
			// A bare `numpy` line has no constraint group at all — that absence is the PIN_DROPPED signal
			// this script exists to surface, so it becomes "" rather than dropping the dependency.
			const [, name, constraint = ""] = reReqDep.exec(t) ?? [];
			if (name === undefined) {
				return null;
			}
			return { name, constraint };
		},
	},
	{
		// Python pyproject (PEP 621 / poetry tables)
		isManifest: (b) => b === "pyproject.toml",
		lockfiles: ["poetry.lock", "uv.lock", "pdm.lock"],
		parse: parseTomlDependency,
	},
	{
		// Ruby Bundler
		isManifest: (b) => b === "gemfile",
		lockfiles: ["Gemfile.lock"],
		parse: (line) => {
			// `gem "puma"` carries no constraint group — an absent pin, not an absent dependency.
			const [, name, constraint = ""] = reGemDep.exec(line) ?? [];
			if (name === undefined) {
				return null;
			}
			return { name, constraint };
		},
	},
	{
		// Maven and XcodeGen spread one dependency over several lines — an artifactId and its version, a
		// url and its bound — and a diff carries only the lines that changed, so the unchanged half may sit
		// outside it. No added, removed or pin label is read from such a subset.
		isManifest: (b) => b === "pom.xml",
		lockfiles: [],
		parse: () => null,
		dependencyLine: /<(?:artifactId|version)>/u,
	},
	{
		// Gradle (Groovy or Kotlin DSL)
		isManifest: (b) => b === "build.gradle" || b === "build.gradle.kts",
		lockfiles: ["gradle.lockfile"],
		parse: (line) => {
			// The version group matches empty for a trailing-colon coordinate (`"g:a:"`); the coordinate
			// group cannot be empty.
			const [, coordinate, constraint = ""] = reGradleDep.exec(line) ?? [];
			if (coordinate === undefined) {
				return null;
			}
			return { name: coordinate, constraint };
		},
	},
	{
		// Swift Package Manager
		isManifest: (b) => b === "package.swift",
		lockfiles: ["Package.resolved"],
		parse: (line) => {
			// The url group is required; the three constraint forms are alternatives, so at most one of
			// them is present on any given line and the range form always yields BOTH of its bounds.
			const [, url, fromVersion, exactVersion, rangeLow, rangeHigh] = reSwiftPkg.exec(line) ?? [];
			if (url === undefined) {
				return null;
			}
			const name =
				url
					.split("/")
					.pop()
					?.replace(/\.git$/u, "") ?? url;
			// from: => caret-like (loose), exact: => exact, range => loose
			const constraint = swiftConstraint(fromVersion, exactVersion, rangeLow, rangeHigh);
			return { name, constraint };
		},
	},
	{
		// XcodeGen project.yml: a package is declared under `packages:` as a url line followed by a
		// constraint line, so it is read as Maven is.
		isManifest: (b) => b === "project.yml" || b === "project.yaml",
		lockfiles: ["Package.resolved"],
		parse: () => null,
		dependencyLine:
			/^\s*(?:url|from|exactVersion|majorVersion|minorVersion|branch|revision):\s*\S/u,
	},
	{
		// Go modules
		isManifest: (b) => b === "go.mod",
		lockfiles: ["go.sum"],
		parse: (line) => {
			// Both groups are required: a go.mod require line without a `v…` version is not matched at all.
			const [, name, version] = reGoMod.exec(line) ?? [];
			if (name === undefined || version === undefined) {
				return null;
			}
			return { name, constraint: version };
		},
	},
];

function basenameLower(path: string): string {
	return (path.split("/").pop() ?? path).toLowerCase();
}

// Escape a dependency name for safe embedding in a RegExp (names can contain ., -, /, @ and similar).
function escapeRegExp(s: string): string {
	return s.replaceAll(/[.*+?^${}()|[\]\\]/gu, String.raw`\$&`);
}

function ecosystemFor(path: string): Ecosystem | null {
	const base = basenameLower(path);
	return ECOSYSTEMS.find((e) => e.isManifest(base)) ?? null;
}

// Classify the constraint delta for a dependency present on both sides (added + removed for same name).
function classifyDelta(oldC: string, newC: string): string {
	const o = oldC.trim();
	const n = newC.trim();
	// Identical constraint text on both sides means the -X/+X pair differs only by whitespace/newline (e.g. a
	// trailing-newline reflow): there is no version change, so surface a neutral no-change fact rather than a
	// phantom version bump. UNCHANGED is informational only and is never counted toward the bump tally.
	if (o === n) {
		return "UNCHANGED";
	}
	const oExact = !isLoose(o);
	const nLoose = isLoose(n);
	if (n === "" && o !== "") {
		return "PIN_DROPPED";
	}
	if (oExact && nLoose) {
		return "PIN_LOOSENED";
	}
	return "BUMPED";
}

// Collect { name -> constraint } from added/removed manifest lines for a single ecosystem file.
function collectDeps(df: DiffFile, eco: Ecosystem, side: "added" | "removed"): Map<string, string> {
	const out = new Map<string, string>();
	const lines = side === "added" ? df.addedLines : df.removedLines;
	for (const [, content] of lines) {
		const parsed = eco.parse(content);
		if (parsed) {
			out.set(parsed.name, parsed.constraint);
		}
	}
	return out;
}

/** How many captured paths a direction names before it only counts the rest. */
const PATHS_NAMED = 5;

function namedPaths(paths: readonly string[]): string {
	const named = paths.slice(0, PATHS_NAMED).join(", ");
	return paths.length > PATHS_NAMED ? `${named} and ${paths.length - PATHS_NAMED} more` : named;
}

/** The hint's context line: the matched name and constraint on its side, or the delta between the two. */
function dependencyContext(fact: string, name: string, oldC: string, newC: string): string {
	if (fact === "ONLY_ADDED") {
		return `+ ${name} ${newC}`.trim();
	}
	return fact === "ONLY_REMOVED" ? `- ${name} ${oldC}`.trim() : `${name}: ${oldC} -> ${newC}`;
}

export default function changesDependenciesDeliberately(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	const changedManifests = new Set<string>();
	const touchedLockfiles = new Set<string>();
	let onlyAdded = 0;
	let onlyRemoved = 0;
	let pinsLoosened = 0;
	let pinsDropped = 0;
	let bumped = 0;
	let unpairedManifestLines = 0;

	// Where the checkout holds a file with a lockfile's name. A path anywhere in the repository is not
	// evidence that it belongs to a changed manifest; the paths are reported for the review to relate.
	const allLockfileNames = new Set(
		ECOSYSTEMS.flatMap((e) => e.lockfiles.map((l) => l.toLowerCase())),
	);
	const checkoutLockfiles: string[] = [];
	for (const ext of ["json", "lock", "yaml", "resolved", "lockfile", "sum"]) {
		for (const f of globFilesSync(`**/*.${ext}`, repoPath)) {
			if (allLockfileNames.has(basenameLower(f))) {
				checkoutLockfiles.push(f);
			}
		}
	}

	for (const [path, df] of diffFiles) {
		const base = basenameLower(path);
		if (allLockfileNames.has(base)) {
			touchedLockfiles.add(path);
			continue;
		}
		const eco = ecosystemFor(path);
		if (!eco) {
			continue;
		}
		changedManifests.add(path);

		const { dependencyLine } = eco;
		if (dependencyLine !== undefined) {
			for (const side of ["removed", "added"] as const) {
				const lines = [...(side === "added" ? df.addedLines : df.removedLines)];
				for (const [ln, content] of lines.filter(([, c]) => dependencyLine.test(c))) {
					unpairedManifestLines += 1;
					hints.push({
						file: path,
						line: ln,
						pattern: "candidate:raw manifest line",
						context: `${side === "added" ? "+" : "-"} ${content.trim()}`.slice(0, 160),
						inDiff: true,
						flags: { ecosystem: base, side },
					});
				}
			}
			continue;
		}
		const added = collectDeps(df, eco, "added");
		const removed = collectDeps(df, eco, "removed");

		// helper to find the diff line for a dependency name on a given side (for hint placement). Match on a
		// quote/word/coordinate boundary, not a bare substring, so a prefix-sharing sibling (react vs
		// react-dom, or a scoped name appearing inside another package's URL) doesn't grab the wrong line.
		const lineFor = (name: string, side: "added" | "removed"): number => {
			const lines = side === "added" ? df.addedLines : df.removedLines;
			const bounded = new RegExp(`(?:^|[^\\w.\\-/])${escapeRegExp(name)}(?:[^\\w.\\-/]|$)`, "u");
			for (const [ln, content] of lines) {
				if (bounded.test(content)) {
					return ln;
				}
			}
			// Fallback: a constructed key (e.g. a Gradle group:name coordinate) may not survive the boundary
			// test against the raw line — keep the substring scan so the hint still lands on a real line.
			for (const [ln, content] of lines) {
				if (content.includes(name)) {
					return ln;
				}
			}
			return 0;
		};

		const allNames = new Set<string>([...added.keys(), ...removed.keys()]);
		for (const name of allNames) {
			const inAdded = added.has(name);
			const inRemoved = removed.has(name);
			let fact: string;
			let side: "added" | "removed" = "added";
			if (inAdded && !inRemoved) {
				fact = "ONLY_ADDED";
				onlyAdded += 1;
			} else if (!inAdded && inRemoved) {
				fact = "ONLY_REMOVED";
				side = "removed";
				onlyRemoved += 1;
			} else {
				fact = classifyDelta(removed.get(name) ?? "", added.get(name) ?? "");
				if (fact === "PIN_LOOSENED") {
					pinsLoosened += 1;
				} else if (fact === "PIN_DROPPED") {
					pinsDropped += 1;
				} else if (fact === "UNCHANGED") {
					// whitespace/newline-only line pair — not a version change, count nothing
				} else {
					bumped += 1;
				}
			}
			const oldC = removed.get(name) ?? "";
			const newC = added.get(name) ?? "";
			const ctx = dependencyContext(fact, name, oldC, newC);
			hints.push({
				file: path,
				line: lineFor(name, side),
				pattern: `candidate:${fact}`,
				context: ctx.slice(0, 160),
				inDiff: true,
				flags: { ecosystem: base, name },
			});
		}
	}

	const lockfilePresent = checkoutLockfiles.length > 0 || touchedLockfiles.size > 0;
	const listed = hints.slice(0, 40);
	const rawLinesListed = listed.filter((h) => h.pattern === "candidate:raw manifest line").length;

	const directions: string[] = [];
	if (changedManifests.size > 0) {
		directions.push(
			`Manifest-named file(s) changed (${changedManifests.size}). The name alone is no occasion: a changed external dependency declaration, resolution, source or pin inside one is, and internal target, test-target, scheme or build-setting wiring alone is not. Candidate lines, matched by shape and not yet placed in a dependency section: ${onlyAdded} only on an added line, ${onlyRemoved} only on a removed line, ${pinsLoosened} pin(s) loosened, ${pinsDropped} pin(s) dropped, ${bumped} version bump(s). A metadata field such as a package.json engines entry or a Cargo rust-version has the same shape, and a name on one side only may be a moved or reformatted line rather than a new or dropped dependency — read the section around each before treating it as a dependency change${unpairedManifestLines > 0 ? `; the ${unpairedManifestLines} raw multi-line manifest line(s) are not in these counts, so a zero here does not show that nothing changed` : ""}. Then investigate whether each dependency constraint change is deliberate and appropriately bounded.`,
		);
		if (hints.length === 0) {
			directions.push(
				"No changed line in these manifests has the dependency shape this script reads. Read the changed sections before deciding: a declaration spread over lines can escape a per-line reading, while internal wiring such as a target dependency, a test target or a scheme entry declares no external dependency.",
			);
		}
		if (unpairedManifestLines > 0) {
			directions.push(
				`${unpairedManifestLines} changed dependency line(s) in a pom.xml or XcodeGen project.yml carry no added, removed or pin label${rawLinesListed < unpairedManifestLines ? `, and only ${rawLinesListed} of them are listed as raw lines here — read the manifest diffs for the other ${unpairedManifestLines - rawLinesListed}` : " and are listed as raw lines"}: these manifests spread one dependency over several lines and the diff shows only the changed ones. Read the manifest around each to tell an addition from a version change or a reordering; a pom.xml coordinate may also be a build plugin or a parent/BOM rather than a dependency.`,
			);
		}
		if (lockfilePresent) {
			directions.push(
				`Lockfile-named file(s) in the checkout: ${checkoutLockfiles.length === 0 ? "none" : namedPaths(checkoutLockfiles)}; touched in this diff: ${touchedLockfiles.size === 0 ? "none" : namedPaths([...touchedLockfiles])}. A lockfile answers for a changed manifest when the ecosystem resolves that manifest through it — beside it, or at a parent workspace root whose configuration includes it — so read the paths and that configuration before expecting a matching update.`,
			);
		} else {
			directions.push(
				"No file with a lockfile name these ecosystems write was found in the checkout or touched in the diff — investigate whether the ecosystem expects a committed lockfile to make the resolved versions reproducible.",
			);
		}
	}

	return {
		hints: listed,
		metrics: {
			manifestsChanged: changedManifests.size,
			onlyAdded,
			onlyRemoved,
			pinsLoosened,
			pinsDropped,
			bumped,
			unpairedManifestLines,
			rawLinesListed,
			lockfilesTouched: touchedLockfiles.size,
			lockfilePresent: lockfilePresent ? 1 : 0,
		},
		directions,
	};
}

// Precompute HINTS for documents-public-api-and-behaviour-changes. Surfaces FACTS ONLY — the LLM judges.
//
// Two STRUCTURAL leads a diff hunk alone cannot reveal: whether a manifest declares a library/framework
// product, and whether the declarations the diff adds are EXPORTED or internal/private. Neither settles the
// public surface: an app without a library product can still expose an HTTP, configuration or wire contract
// to separate consumers, which the review investigates. A modifier-less Swift declaration is INTERNAL — not
// public — so the export-status table classifies it as internal. We surface {hasPublicProduct,
// changedPublicSymbols, changedInternalSymbols} and let the model decide whether documentation was owed. The
// table is keyed off file extension: adding a language = one row, no engine change.
import { isCommentLine } from "../lib/declarations.ts";
import { findFiles, readFileLines } from "../lib/grep.ts";
import { languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// ── (1) Public-product manifest scan ──────────────────────────────────────────────────────────────────────
// Each manifest filename maps to a predicate over its raw text that answers "does this declare a consumable
// library/framework product?". One row per ecosystem; the predicate stays neutral (a structural test, no observation).
const PRODUCT_MANIFESTS: [RegExp, (text: string) => boolean][] = [
	// Swift Package Manager: a `.library(...)` product.
	[/(?:^|\/)Package\.swift$/u, (t) => /\.library\s*\(/u.test(t)],
	// npm: a non-private package that declares an entry/types surface for consumers.
	[
		/(?:^|\/)package\.json$/u,
		(t) =>
			!/"private"\s*:\s*true/u.test(t) && /"(?:main|module|exports|types|typings)"\s*:/u.test(t),
	],
	// Maven: packaged as a real artifact (jar/etc.), not an aggregator pom.
	[/(?:^|\/)pom\.xml$/u, (t) => !/<packaging>\s*pom\s*<\/packaging>/u.test(t)],
	// Gradle: applies the java-library plugin or a publishing plugin.
	[
		/(?:^|\/)build\.gradle(?:\.kts)?$/u,
		(t) =>
			/(?:java-library|maven-publish|`maven-publish`|com\.vanniktech\.maven\.publish)/u.test(t),
	],
	// Python: declares packages to distribute.
	[/(?:^|\/)setup\.py$/u, (t) => /(?:packages\s*=|find_packages\s*\()/u.test(t)],
	[/(?:^|\/)setup\.cfg$/u, (t) => /\[options\][^[]*packages\s*=/u.test(t)],
	[/(?:^|\/)pyproject\.toml$/u, (t) => /(?:\[project\]|\[tool\.poetry\]|packages\s*=)/u.test(t)],
	// Go: a module declaration makes the package importable by others.
	[/(?:^|\/)go\.mod$/u, (t) => /^module\s+\S+/mu.test(t)],
];

const MANIFEST_NAMES = ["swift", "json", "xml", "gradle", "kts", "py", "cfg", "toml", "mod"];

// ── (2) Per-language export status of a CHANGED declaration ────────────────────────────────────────────────
// For each language: detect that a line declares a symbol, and whether that symbol is PUBLIC (exported) or not.
// `isPublic` is only consulted when `decl` matches. Modifier-less Swift is INTERNAL, not public.
interface ExportRule {
	// line introduces a named declaration (func/class/type/var/const)
	decl: RegExp;
	// is that declaration part of the public surface?
	isPublic: (line: string) => boolean;
}

const EXPORT_RULES: Record<string, ExportRule> = {
	// Swift: public/open are exported; modifier-less / internal / private / fileprivate are NOT public.
	swift: {
		decl: /\b(?:func|class|struct|enum|protocol|extension|var|let|typealias|actor|init)\b/u,
		isPublic: (l) => /\b(?:public|open)\b/u.test(l),
	},
	// TypeScript and JavaScript: an `export` keyword (or `export default`) marks the public surface.
	typescript: {
		decl: /\b(?:function|class|interface|type|enum|const|let|var|namespace)\b/u,
		isPublic: (l) => /\bexport\b/u.test(l),
	},
	javascript: {
		decl: /\b(?:function|class|const|let|var)\b/u,
		isPublic: (l) => /\bexport\b/u.test(l),
	},
	// Java: only `public` declarations are part of the API; package-private/protected/private are not.
	java: {
		decl: /\b(?:class|interface|enum|record|void|[A-Z][A-Za-z0-9_<>[\]]*)\s+[A-Za-z_]\w*\s*[({]/u,
		isPublic: (l) => /\bpublic\b/u.test(l),
	},
	// Kotlin: declarations are public by default; private/internal/protected demote them.
	kotlin: {
		decl: /\b(?:fun|class|interface|object|val|var)\b/u,
		isPublic: (l) => !/\b(?:private|internal|protected)\b/u.test(l),
	},
	// Python: a leading-underscore name is private by convention; anything else is public.
	python: {
		decl: /^\s*(?:def|class)\s+[A-Za-z_]/u,
		isPublic: (l) => !/^\s*(?:def|class)\s+_/u.test(l),
	},
	// Go: an exported identifier starts with an upper-case letter.
	go: {
		decl: /^\s*(?:func|type|var|const)\s+[A-Za-z_]/u,
		isPublic: (l) => /^\s*(?:func|type|var|const)\s+(?:\([^)]*\)\s*)?[A-Z]/u.test(l),
	},
};

// (1) Does the repo declare a public library/framework product?
async function declaresPublicProduct(repoPath: string): Promise<boolean> {
	for (const ext of MANIFEST_NAMES) {
		for (const manifestPath of findFiles(repoPath, ext)) {
			const matcher = PRODUCT_MANIFESTS.find(([re]) => re.test(manifestPath));
			if (!matcher) {
				continue;
			}
			const lines = await readFileLines(manifestPath);
			const text = [...lines.values()].join("\n");
			if (matcher[1](text)) {
				return true;
			}
		}
	}
	return false;
}

export default async function documentsPublicApiAndBehaviourChanges(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_m: PullRequestMetadata,
) {
	const hasPublicProduct = await declaresPublicProduct(repoPath);

	// (2) Classify each declaration ADDED in the diff as public (exported) or internal.
	const hints: Hint[] = [];
	let changedPublicSymbols = 0;
	let changedInternalSymbols = 0;
	let filesScanned = 0;
	let linesAdded = 0;
	for (const [path, df] of diffFiles) {
		const lang = languageOf(path);
		if (lang === null) {
			continue;
		}
		const rule = EXPORT_RULES[lang];
		if (!rule) {
			continue;
		}
		filesScanned += 1;
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, lang)) {
				continue;
			}
			linesAdded += 1;
			if (!rule.decl.test(content)) {
				continue;
			}
			const isPublic = rule.isPublic(content);
			if (isPublic) {
				changedPublicSymbols += 1;
			} else {
				changedInternalSymbols += 1;
			}
			if (hints.length < 40) {
				hints.push({
					file: path,
					line,
					pattern: `${lang}:${isPublic ? "public-decl" : "internal-decl"}`,
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: { exported: isPublic },
				});
			}
		}
	}

	const directions: string[] = [];
	if (!hasPublicProduct) {
		directions.push(
			"No public library/framework product was detected in the repo manifests (no SwiftPM .library, non-private package.json entry, publishable Maven/Gradle artifact, distributable Python package, or Go module) — investigate whether this repo exposes any public API surface a consumer depends on before deciding documentation was owed.",
		);
	}
	if (changedPublicSymbols > 0) {
		directions.push(
			`The diff adds ${changedPublicSymbols} exported/public declaration(s)${hasPublicProduct ? " in a repo that ships a public product" : ""} — investigate whether their documented behaviour or signature changed and whether that change is reflected in docs/comments.`,
		);
	}
	if (changedInternalSymbols > 0 && changedPublicSymbols === 0) {
		directions.push(
			`The diff adds ${changedInternalSymbols} declaration(s) but none are exported/public (e.g. modifier-less Swift is internal, non-exported TS, package-private Java, leading-underscore Python) — investigate whether any public-facing behaviour actually changed before expecting public-API documentation.`,
		);
	}

	return {
		hints,
		metrics: {
			hasPublicProduct: hasPublicProduct ? 1 : 0,
			changedPublicSymbols,
			changedInternalSymbols,
			filesScanned,
			linesAdded,
		},
		directions,
	};
}

// Precompute FACTS for commits-are-atomic-and-cohesive: one row per authored commit — its subject,
// whether it joins clauses, and the files it touched with their line counts and moves — read from the
// commit record. The criteria say what one logical change is and the model judges the partition; a
// flag is a place to look, never a verdict.
import { readCapturedCommits } from "../lib/change.ts";
import { commitRows, describeCommitCount, subjectFacts } from "../lib/commit-subjects.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default async function commitsAreAtomicAndCohesive(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const captured = await readCapturedCommits(contextDir);
	const facts = subjectFacts(captured ?? []);
	const authored = facts.filter((f) => !f.merge);
	let directions = [
		describeCommitCount(facts),
		"`joinedClauses` marks a subject that joins clauses with 'and', '&', '+', a comma, a semicolon or a sentence break, or a body with two or more bullets; `moved` counts files renamed with no line changed. Both describe the record, not how many changes a commit holds.",
	];
	if (captured === null) {
		directions = [
			"commits.json is missing or malformed: a collection gap, not a history without authored commits.",
		];
	} else if (authored.length === 0) {
		directions = ["No authored commit in the reviewed range: only merge commits, or none."];
	}
	return {
		hints: commitRows(facts, contextReference),
		metrics:
			captured === null
				? {}
				: {
						authoredCommits: authored.length,
						mergeCommits: facts.length - authored.length,
						joinedSubjects: authored.filter((f) => f.joinedClauses).length,
					},
		directions,
	};
}

// Precompute FACTS for breaks-large-work-into-trackable-subtasks: the task-list items and issue-number
// mentions the body carries, its labels, and the captured sub-issue rollup with its source. Whether the
// work is large and whether it is broken down are the criteria's to decide from the text.
import {
	bodyFact,
	classifyIssue,
	subIssueRollup,
	type IssueMetadata,
} from "../lib/issue-classification.ts";
import { checkableItems } from "../lib/review.ts";
import type { Hint } from "../lib/types.ts";

export default function breaksLargeWorkIntoTrackableSubtasks(
	_repo: string,
	_diff: Map<string, unknown>,
	m: IssueMetadata,
) {
	const shape = classifyIssue(m);
	const { body, labels } = shape;
	const items = checkableItems(body);
	const checked = items.filter((item) => item.checked).length;
	const issueMentions = new Set((body.match(/(?:^|\s)#\d+\b/gu) ?? []).map((s) => s.trim())).size;
	const rollup = subIssueRollup(m);

	const directions = [
		...bodyFact(shape),
		`Captured: ${String(items.length)} task-list item(s) (${String(checked)} ticked), ${String(issueMentions)} issue-number mention(s), ${rollup.text}; labels ${labels.join(", ") || "none"}. Judge the standard once: whether the work is large and whether these items or mentions break it down is read from what they say, never from how many there are.`,
	];

	const hints: Hint[] = [];
	return {
		hints,
		metrics: {
			bodyLength: body.length,
			taskCheckboxes: items.length,
			childIssueRefs: issueMentions,
			...rollup.metrics,
		},
		directions,
	};
}

// Precompute FACTS for links-the-change-to-its-issue: where this pull request names an issue — title,
// body, source branch, commit subjects, linked work items — each resolved against the project
// inventory and the linked items, and, when it names none, whether the project tracks issues at all.
// The review decides whether a reference is a link; the script says where each candidate was found
// and what the inventory holds under that number in that repository.
import {
	contextFile,
	isOpenState,
	readProjectInventory,
	repositoryIssues,
	type InventoryItem,
} from "../lib/context.ts";
import { text } from "../lib/practice-contract.ts";
import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
	withoutHtmlComments,
} from "../lib/references.ts";
import { readLinkedWorkItems } from "../lib/review.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/**
 * Qualified references cannot become local `#N` candidates. GitLab's `project#N` shortcut needs
 * provider namespace authority the captured metadata does not carry, so its target remains unknown.
 */
const QUALIFIED_REF =
	/(?<![\w./-])(?<target>[\w.-]+(?:\/[\w.-]+)*)#(?<number>\d+)(?![\w]|\.[0-9])/gu;

const byNumber = (rows: InventoryItem[] | null) =>
	rows === null ? null : new Map(rows.map((issue) => [issue.number, issue]));

export default async function linksTheChangeToItsIssue(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const focal = text(metadata.repository_full_name);
	const linked = await readLinkedWorkItems(contextDir);
	const inventory = await readProjectInventory(contextDir);
	// A plain #N is the admitted repository's, by its id; a qualified path names a repository of the same
	// provider. A full name alone is unique only within one provider, so no id leaves the scope unknown.
	const { repository_id: repositoryId, provider_id: providerId } = metadata;
	const focalIssues = repositoryIssues(
		inventory,
		typeof repositoryId === "number" ? { repositoryId } : null,
	);
	const issuesOf = (path: string) =>
		byNumber(
			repositoryIssues(
				inventory,
				typeof providerId === "number" ? { providerId, fullName: path } : null,
			),
		);
	const local = byNumber(focalIssues);
	const hints: Hint[] = [];
	const row = (
		where: string,
		pattern: string,
		reference: string,
		issue: InventoryItem | undefined,
		flags: Hint["flags"],
	) => {
		hints.push({
			file: where,
			line: 0,
			pattern,
			context: `${reference}${issue === undefined ? "" : ` ${issue.title}`}`,
			inDiff: false,
			flags,
		});
	};
	const add = (where: string, numbers: number[], closing: boolean) => {
		for (const n of numbers) {
			const issue = local?.get(n);
			const candidates = (linked ?? []).filter((item) => item.number === n);
			const matched = issue?.url !== undefined && candidates.some((item) => item.url === issue.url);
			row(where, closing ? "closing reference" : "issue reference", `#${n}`, issue, {
				number: n,
				where,
				inInventory: local === null ? "unknown" : issue !== undefined,
				title: issue?.title ?? "",
				state: issue?.state ?? "",
				inLinkedItems: candidates.length === 0 ? false : matched || "unknown",
			});
		}
	};
	const qualified = (where: string, source: string) => {
		const seen = new Set<string>();
		for (const match of withoutHtmlComments(source).matchAll(QUALIFIED_REF)) {
			const target = match.groups?.target ?? "";
			const n = Number(match.groups?.number);
			const reference = `${target}#${n}`;
			if (!Number.isSafeInteger(n) || n <= 0 || seen.has(reference)) {
				continue;
			}
			seen.add(reference);
			const rows = target.includes("/") ? issuesOf(target) : null;
			const issue = rows?.get(n);
			row(where, "qualified issue reference", reference, issue, {
				number: n,
				target,
				where,
				inInventory: rows === null ? "unknown" : issue !== undefined,
				title: issue?.title ?? "",
				state: issue?.state ?? "",
			});
		}
	};
	const unqualified = (source: string) => source.replaceAll(QUALIFIED_REF, " ");
	// The provider's closing candidates come first: a link made in the UI or through a cross-project
	// reference matches nothing in the text. A candidate may belong to another repository, so it is
	// placed in the inventory only by its address, never by its number.
	const providerLinks = (linked ?? []).filter((item) => item.how === "closesOnMerge");
	const providerFile = `${contextFile(contextReference, "linked_work_items.json")} (how: closesOnMerge)`;
	for (const item of providerLinks) {
		const matches =
			item.url === undefined ||
			!Number.isSafeInteger(providerId) ||
			typeof providerId !== "number" ||
			providerId <= 0
				? []
				: (inventory?.issues?.filter(
						(candidate) =>
							candidate.url === item.url &&
							candidate.providerId === providerId &&
							candidate.repositoryId !== undefined,
					) ?? []);
		const issue = matches.length === 1 ? matches[0] : undefined;
		row(providerFile, "closing reference", `#${item.number}`, issue, {
			number: item.number,
			target: issue?.repository ?? item.url ?? "unknown",
			where: providerFile,
			inInventory: issue === undefined ? "unknown" : true,
			title: item.title,
			state: item.state ?? issue?.state ?? "",
			inLinkedItems: true,
		});
	}
	const title = text(metadata.title);
	const body = text(metadata.body);
	const branch = metadata.source_branch;
	const titleFile = `${contextFile(contextReference, "metadata.json")} (title)`;
	const descriptionFile = contextFile(contextReference, "description.md");
	add(titleFile, issueNumberReferences(unqualified(title)), false);
	qualified(titleFile, title);
	const closing = closingReferences(unqualified(body));
	add(descriptionFile, closing, true);
	add(
		descriptionFile,
		issueNumberReferences(unqualified(body)).filter((n) => !closing.includes(n)),
		false,
	);
	qualified(descriptionFile, body);
	add(
		`${contextFile(contextReference, "metadata.json")} (source_branch)`,
		branchIssueReferences(branch),
		false,
	);
	const referenceOf = (h: Hint) =>
		`${typeof h.flags.target === "string" ? h.flags.target : focal}#${String(h.flags.number)}`;
	const references = new Set(hints.map(referenceOf));
	const metrics = {
		referencesFound: references.size,
		referencesInInventory: new Set(
			hints.filter((h) => h.flags.inInventory === true).map(referenceOf),
		).size,
		closingReferences: hints.filter((h) => h.pattern === "closing reference").length,
		providerClosingLinks: providerLinks.length,
		linkedWorkItems: linked?.length ?? -1,
		inventoryIssues: focalIssues?.length ?? -1,
		inventoryOpenIssues: focalIssues?.filter((i) => isOpenState(i.state)).length ?? -1,
	};
	const candidates = providerLinks
		.map((item) => ` #${String(item.number)} (state ${item.state ?? "not recorded"})`)
		.join(",");
	const linkedSummary =
		linked === null
			? "linked_work_items.json not captured"
			: `${String(linked.length)} captured, ${String(providerLinks.length)} of them provider closing candidates${candidates}`;
	// What the inventory holds for this repository: absent, not attributable to it, or its own counts.
	const held = (absent: string, counts: string) => {
		if (inventory === null) {
			return absent;
		}
		return focalIssues === null
			? `the inventory does not say which of its issues belong to ${focal === "" ? "this repository" : focal}`
			: counts;
	};
	const directions: string[] = [];
	if (references.size > 0) {
		directions.push(
			`Issue-shaped references found: ${[...references].join(", ")}, one row each with what the inventory holds under that number in the repository the reference names, this one (${focal}) for a plain #number (${held("no inventory captured", `${String(metrics.inventoryIssues)} issues in ${focal}`)}), and whether it is among the linked items (${linkedSummary}).`,
		);
	} else {
		directions.push(
			`No #number, closing keyword or branch number in the title, body or branch (${branch}); ${linked === null ? "linked_work_items.json was not captured" : `${String(linked.length)} linked work item(s) captured`}. Read ${contextFile(contextReference, "commits.json")} for a reference in history, then the inventory (${held("not captured", `${String(metrics.inventoryIssues)} issues, ${String(metrics.inventoryOpenIssues)} open, in ${focal}`)}) for an open issue that plainly describes this work.`,
		);
	}
	return { hints: hints.slice(0, 20), metrics, directions };
}

import { contextFile } from "../lib/context.ts";
import { subIssueRollup } from "../lib/issue-classification.ts";
import { text } from "../lib/practice-contract.ts";
// Precompute FACTS for merge-confirms-the-linked-issue-outcome: every captured linked issue, one row
// each — its task-list items as captured, ticked and unticked, its state, and how the change names it.
// Which of them this change implements is the criteria's to decide; a row is a candidate, not an
// occasion.
import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
} from "../lib/references.ts";
import { checkableItems, mergeFacts, readLinkedWorkItems } from "../lib/review.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/** Headings under which an issue states what "done" means without a task list. */
const OUTCOME_HEADING =
	/^\s*#+\s*(?:acceptance criteria|definition of done|dod|expected (?:outcome|result|behaviou?r)|given\b)/imu;

/** How the change names a linked issue, strongest form first. */
function howLinked(
	number: number,
	closing: ReadonlySet<number>,
	named: ReadonlySet<number>,
): string {
	if (closing.has(number)) {
		return "named with a closing keyword in the body";
	}
	return named.has(number)
		? "named by the title, body or branch"
		: "linked through a commit or another item";
}

export default async function mergeConfirmsTheLinkedIssueOutcome(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const body = text(metadata.body);
	const closing = new Set(closingReferences(body));
	const named = new Set([
		...issueNumberReferences(text(metadata.title)),
		...issueNumberReferences(body),
		...branchIssueReferences(metadata.source_branch),
	]);
	const captured = await readLinkedWorkItems(contextDir);
	const linked = captured ?? [];
	const hints: Hint[] = [];
	for (const item of linked) {
		const items = checkableItems(item.body);
		const ticked = items.filter((i) => i.checked).length;
		const heading = OUTCOME_HEADING.test(item.body);
		const rollup = subIssueRollup({
			sub_issues_total: item.subIssuesTotal,
			sub_issues_completed: item.subIssuesCompleted,
			sub_issues_source: item.subIssuesSource,
		});
		const subIssues = rollup.total;
		const checkable = items.length > 0 || heading || (subIssues ?? 0) > 0;
		let pattern = checkable ? "checkable outcome" : "no checkable outcome";
		if (subIssues === undefined || (item.subIssuesSource === "children" && subIssues === 0)) {
			pattern = checkable ? pattern : "no task list or outcome heading";
		}
		const rollupFlags: Hint["flags"] = subIssues === undefined ? {} : { subIssuesTotal: subIssues };
		// The provider's own link outranks what the text says: a link made in the UI matches no `#N`.
		const how =
			item.how === "closesOnMerge"
				? "a provider closing candidate"
				: howLinked(item.number, closing, named);
		hints.push({
			file: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),
			line: items[0]?.line ?? 0,
			pattern,
			context: `#${String(item.number)} ${item.title} — ${how}; ${String(items.length)} task-list item(s), ${String(ticked)} ticked as captured${heading ? "; an outcome heading" : ""}; ${rollup.text}; state ${item.state ?? "unknown"}`,
			inDiff: false,
			flags: {
				number: item.number,
				how,
				taskItems: items.length,
				ticked,
				unticked: items.length - ticked,
				outcomeHeading: heading,
				...rollupFlags,
				state: item.state ?? "",
			},
		});
	}
	const candidates = hints.filter((h) => h.pattern === "checkable outcome");
	const directions: string[] = [];
	if (!mergeFacts(metadata).merged) {
		directions.push("The change is not merged; the practice's occasion is the merge.");
	} else if (captured === null) {
		directions.push(
			"linked_work_items.json was not captured: a collection gap, not a change without a linked issue.",
		);
	} else if (candidates.length === 0) {
		directions.push(
			linked.length === 0
				? "The capture holds no linked issue; there is no stated outcome to confirm."
				: "No captured linked issue carries a task list, an acceptance or Definition-of-Done heading or a positive captured sub-issue count; a rollup the provider does not report says nothing about sub-issues.",
		);
	} else {
		directions.push(
			`${String(candidates.length)} captured linked issue(s) state a checkable outcome. Each is a candidate: the criteria decide which of them this change implements, from the provider's closing link and the author's own words; a mention alone asks nothing of it. For an issue it implements, assess confirmation in the captured record: its items ticked as captured, or the description or a closing comment naming which items are done and where the rest moves. Work delivered in the diff but neither ticked nor named is unconfirmed. A confirmation captured after the merge counts; when it was written is unknown unless independently dated evidence establishes it.`,
		);
	}
	return {
		hints,
		metrics: {
			linkedItems: linked.length,
			checkableItems: candidates.length,
			untickedItems: candidates.reduce((sum, h) => sum + Number(h.flags.unticked), 0),
		},
		directions,
	};
}

import { contextFile } from "../lib/context.ts";
// Precompute FACTS for defers-review-asks-into-tracked-work: every ask a reviewer made, one row
// each, with what the record shows beside it — whether the change touches the file the ask is on,
// whether the author replied and what the reply names, whether the reviewer had a later word on it
// or approved after it, whether the thread was marked resolved. The review decides for each row
// whether the ask was addressed, deferred into tracked work, waived or merged past; a thread's
// RESOLVED mark is who clicked it, not what happened to the ask.
import { issueNumberReferences } from "../lib/references.ts";
import {
	type GeneralComment,
	type ReviewComment,
	changeNear,
	excerpt,
	later,
	readGeneralComments,
	readReviewComments,
	readReviewThreads,
	reviewerCommentRows,
} from "../lib/review.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/** Words a reply uses to put an ask off rather than answer it. */
const DEFERRAL =
	/\b(?:later|next (?:mr|pr|merge request|pull request|sprint|iteration)|follow[- ]?up|will (?:do|add|fix|revisit|look)|todo|not (?:in|for) this (?:mr|pr)|separate (?:mr|pr|issue)|future)\b/iu;

/** Words a reviewer uses to drop an ask rather than keep it. */
const WAIVER =
	/\b(?:fine to skip|not needed|no need|never mind|nevermind|ignore|optional|nit|non[- ]blocking|up to you|can be skipped)\b/iu;

export default async function defersReviewAsksIntoTrackedWork(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const author = metadata.author ?? "";
	const inline = await readReviewComments(contextDir);
	const general = await readGeneralComments(contextDir);
	const record = await readReviewThreads(contextDir);
	const decisions = record?.decisions ?? [];
	const hints: Hint[] = [];
	const byOthers = (comment: { author?: string }) =>
		comment.author !== undefined && comment.author !== author;
	const approvedAfter = (at: string | undefined) =>
		decisions.some(
			(d) => d.state === "APPROVED" && d.dismissed !== true && later(d.submittedAt, at),
		);
	// An inline ask: the first comment in a thread by someone other than the author. The author's
	// later comments in the thread are its answers; the others' later comments there are the
	// reviewer's last word on it, not new asks.
	const inlineAsks = reviewerCommentRows(inline ?? [], record?.threads ?? [], author).filter(
		(r) => r.opensThread,
	);
	for (const ask of inlineAsks) {
		hints.push(
			row(ask.comment, ask.replies, ask.followUps, diffFiles, contextReference, {
				threadResolved: ask.thread?.state === "RESOLVED",
				approvedAfterAsk: approvedAfter(ask.comment.createdAt),
			}),
		);
	}
	// A conversation ask: a general comment by someone other than the author; the author's later
	// general comments are the candidate answers, the others' later ones the follow-ups.
	const conversationAsks = (general ?? []).filter(byOthers);
	for (const ask of conversationAsks) {
		const afterAsk = (c: GeneralComment) => later(c.createdAt, ask.createdAt);
		const replies = (general ?? []).filter((c) => c.author === author && afterAsk(c));
		const followUps = (general ?? []).filter((c) => byOthers(c) && afterAsk(c));
		hints.push(
			row({ ...ask, path: "", outdated: false }, replies, followUps, diffFiles, contextReference, {
				threadResolved: false,
				approvedAfterAsk: approvedAfter(ask.createdAt),
			}),
		);
	}
	const directions: string[] = [];
	if (inline === null || general === null) {
		directions.push(
			"A required comments file is missing or malformed (comments.json or general_comments.json): report a collection gap and record no observation; an unread source does not establish that no ask exists.",
		);
	} else if (hints.length === 0) {
		directions.push(
			`No comment by anyone other than the author in the captured record (${inline.length} inline comment(s), ${general.length} conversation comment(s)): with no ask, the occasion did not arise.`,
		);
	} else {
		directions.push(
			`${String(hints.length)} comment(s) by others are listed, one row each; a remark that asks nothing of this change is not an ask. Decide every ask: one about the code is addressed when the head diff carries the change asked for; one about the pull request itself — mark it ready, retitle it, link an issue, fill in the description — when the captured record shows it done (metadata.json, description.md, the linked work items), and a merged pull request was not a draft when it merged; deferred into tracked work when the author's reply names an issue or the description defers it to one; waived when the reviewer drops the ask in their own words, in the ask or in a follow-up, otherwise deferred bare. A later approval alone does not establish a waiver. A RESOLVED thread says nothing by itself, and "approved on the condition that you do it next time" is a deferral to track, not a waiver.`,
			"A two-part ask is two asks: address one part and the other still stands.",
		);
	}
	return {
		hints,
		metrics: {
			asks: hints.length,
			inlineAsks: inlineAsks.length,
			conversationAsks: conversationAsks.length,
			asksWithAuthorReply: hints.filter((h) => h.flags.authorReplied === true).length,
			asksNamingAnIssueInReply: hints.filter((h) => h.flags.issueNamedInReply === true).length,
			commentsFileAbsent: inline === null ? 1 : 0,
			generalCommentsFileAbsent: general === null ? 1 : 0,
		},
		directions,
	};
}

function row(
	ask: ReviewComment | (GeneralComment & { path: string; outdated: boolean }),
	replies: readonly { body: string }[],
	followUps: readonly { body: string }[],
	diffFiles: Map<string, DiffFile>,
	contextReference: string,
	record: { threadResolved: boolean; approvedAfterAsk: boolean },
): Hint {
	const replyText = replies.map((r) => r.body).join("\n");
	const followUpText = followUps.map((r) => r.body).join("\n");
	const line = "line" in ask ? ask.line : undefined;
	const flags: Hint["flags"] = {
		by: ask.author ?? "",
		at: ask.createdAt ?? "",
		authorReplied: replies.length > 0,
		issueNamedInReply: issueNumberReferences(replyText).length > 0,
		deferralWordsInReply: DEFERRAL.test(replyText),
		waiverWordsInAsk: WAIVER.test(ask.body),
		reviewerFollowedUp: followUps.length > 0,
		waiverWordsInFollowUp: WAIVER.test(followUpText),
		approvedAfterAsk: record.approvedAfterAsk,
		threadResolved: record.threadResolved,
	};
	if (ask.path !== "") {
		flags.fileInChange = diffFiles.has(ask.path);
		flags.changeNearLine = changeNear(diffFiles.get(ask.path), line);
		flags.outdated = ask.outdated;
	}
	return {
		file: ask.path === "" ? contextFile(contextReference, "general_comments.json") : ask.path,
		line: line ?? 0,
		pattern: ask.path === "" ? "conversation ask" : "inline ask",
		context: excerpt(ask.body),
		inDiff: false,
		flags,
	};
}

// Precompute FACTS for merges-only-after-approval: the merge as the record holds it — who merged,
// when, the provider's own review decision — captured decision rows placed against the merge instant.
// Currentness and history coverage remain separate from this advisory ordering.
import {
	decisionRows,
	lastDecisionPerReviewer,
	mergeFacts,
	mergeRow,
	readReviewThreads,
} from "../lib/review.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

export default async function mergesOnlyAfterApproval(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const merge = mergeFacts(metadata);
	const record = await readReviewThreads(contextDir);
	const decisions = record?.decisions ?? [];
	const rows = decisionRows(decisions, merge, contextReference);
	const last = decisionRows(lastDecisionPerReviewer(decisions), merge, contextReference).map(
		(row) => ({
			...row,
			pattern: "last decision by reviewer",
		}),
	);
	const approvalsBeforeMergeByOthers = rows.filter(
		(r) =>
			r.flags.state === "APPROVED" &&
			r.flags.beforeMerge === true &&
			r.flags.isAuthor !== true &&
			r.flags.dismissed !== true &&
			r.flags.bot !== true,
	).length;
	const unknownDecisionTimes = decisions.filter((d) => d.submittedAt === undefined).length;
	const directions: string[] = [];
	if (!merge.merged) {
		directions.push("The pull request is not merged: the occasion did not arise.");
	} else if (record === null) {
		directions.push(
			"No review threads file was captured (review_threads.json): the decision record is not available here.",
		);
	} else {
		directions.push(
			`Merged${merge.mergedBy === undefined ? "" : ` by ${merge.mergedBy}`}${merge.mergedByIsAuthor ? " (the author)" : ""}${merge.mergedAt === undefined ? "" : ` at ${merge.mergedAt}`}; ${decisions.length} captured decision(s), ${approvalsBeforeMergeByOthers} of them an undismissed APPROVED before the merge by an account other than the author's that is not marked bot; the last captured decision of each reviewer whose decision times are all known is listed apart.`,
		);
		if (unknownDecisionTimes > 0) {
			directions.push(
				`${unknownDecisionTimes} decision time(s) are unknown: the dated approval count is a lower bound, and no historical last decision is established for those reviewers.`,
			);
		}
		directions.push(
			"Read decisionHistoryComplete in review_threads.json: row ordering does not establish complete historical coverage. Apply the practice criteria to that qualification.",
		);
	}
	return {
		hints: [mergeRow(metadata, merge, contextReference), ...rows, ...last],
		metrics: {
			merged: merge.merged ? 1 : 0,
			mergedByIsAuthor: merge.mergedByIsAuthor ? 1 : 0,
			decisions: decisions.length,
			unknownDecisionTimes,
			approvalsBeforeMergeByOthers,
			decisionsByBots: decisions.filter((d) => d.bot).length,
			threadsFileAbsent: record === null ? 1 : 0,
		},
		directions,
	};
}

// Precompute FACTS for plans-the-work-in-an-issue-first: when each issue the change names as its own
// was opened, when the change's earliest commit was authored, and the time between them. The practice
// asks one question of two timestamps; the script puts both beside each other so the review reads
// them rather than reasons around them.
import { readCapturedCommits } from "../lib/change.ts";
import { contextFile } from "../lib/context.ts";
import { text } from "../lib/practice-contract.ts";
import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
	relatedReferences,
} from "../lib/references.ts";
import { millisBetween, readLinkedWorkItemCapture } from "../lib/review.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

/** The two moments in one sentence, the way the cell reads them. */
function relationOf(issueToFirstCommit: number | null): string {
	if (issueToFirstCommit === null) {
		return "the captured commits do not establish the earliest authored time; the order is UNDETERMINED";
	}
	return issueToFirstCommit >= 0
		? `the earliest commit was authored ${hours(issueToFirstCommit)} h after the issue was opened`
		: `the issue was opened ${hours(-issueToFirstCommit)} h after the earliest commit was authored`;
}

/** Hours with one decimal, signed: positive when `to` is later than `from`. */
function hours(millis: number): string {
	return (millis / 3_600_000).toFixed(1);
}

export default async function plansTheWorkInAnIssueFirst(
	_repoPath: string,
	_diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir: string | undefined,
	_changeDir: string | undefined,
	contextReference: string,
) {
	const hints: Hint[] = [];
	const directions: string[] = [];
	const body = text(metadata.body);
	const title = text(metadata.title);
	const capture = await readLinkedWorkItemCapture(contextDir);
	const linked = capture?.items ?? null;
	const named = new Map<number, string[]>();
	const name = (how: string, numbers: number[]) => {
		for (const n of numbers) {
			named.set(n, [...(named.get(n) ?? []), how]);
		}
	};
	name(
		"provider closing link",
		(linked ?? []).filter((item) => item.how === "closesOnMerge").map((item) => item.number),
	);
	name("closing keyword", closingReferences(body));
	name("title", issueNumberReferences(title));
	name("branch", branchIssueReferences(metadata.source_branch));
	name("Related to", relatedReferences(body));
	const capturedCommits = await readCapturedCommits(contextDir);
	const commitsCaptured = capturedCommits !== null;
	const commits = capturedCommits ?? [];
	const authored = commits
		.filter((commit) => Number.isFinite(Date.parse(commit.authoredAt)))
		.toSorted((a, b) => Date.parse(a.authoredAt) - Date.parse(b.authoredAt));
	const first = authored.length === commits.length ? authored[0] : undefined;
	let earliestDeltaMinutes = Number.NaN;
	for (const item of linked ?? []) {
		const namedBy = named.get(item.number)?.join(", ");
		if (namedBy === undefined) {
			continue;
		}
		const toFirstCommit = millisBetween(item.createdAt, first?.authoredAt);
		const flags: Hint["flags"] = {
			number: item.number,
			namedBy,
			providerLink: item.how ?? "",
			openedAt: item.createdAt ?? "",
		};
		if (first !== undefined) {
			flags.firstCommit = first.sha.slice(0, 7);
			flags.firstCommitAuthoredAt = first.authoredAt;
		}
		if (toFirstCommit !== null) {
			flags.hoursFromIssueToFirstCommit = hours(toFirstCommit);
			const minutes = -toFirstCommit / 60_000;
			if (Number.isNaN(earliestDeltaMinutes) || minutes > earliestDeltaMinutes) {
				earliestDeltaMinutes = minutes;
			}
		}
		let relation =
			"the commit record is missing or malformed: a collection gap, not a timing observation";
		if (commitsCaptured) {
			relation =
				item.createdAt === undefined
					? "its opening time is not captured, so the order cannot be read"
					: relationOf(toFirstCommit);
		}
		hints.push({
			file: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),
			line: 0,
			pattern: "candidate issue",
			context: `#${String(item.number)} (named by ${namedBy}; captured as ${item.how ?? "an unclassified link"}) opened ${item.createdAt ?? "(unknown)"}; ${relation}`,
			inDiff: false,
			flags,
		});
	}
	const numbers = [...named.keys()].map((n) => `#${String(n)}`).join(", ");
	// A named number this repository holds no synchronized issue for may be an issue not yet
	// synchronized or a reference elsewhere; the record cannot say which.
	const unresolved = [...named.keys()].filter((n) => capture?.unresolved.includes(n) ?? false);
	if (!commitsCaptured) {
		directions.push(
			"The commit record is missing or malformed: report a collection gap and record no observation, never UNDETERMINED.",
		);
	} else if (capture === null) {
		directions.push(
			`${contextFile(contextReference, "linked_work_items.json")} was not captured: a collection gap, not a change without an issue.`,
		);
	} else if (hints.length === 0 && unresolved.length === 0) {
		directions.push(
			"No issue of this repository is named by a provider closing link, a closing keyword, the title, the branch or a `Related to #N`; without an issue this change implements there is nothing to have planned in.",
		);
	} else {
		if (unresolved.length > 0) {
			directions.push(
				`The named issue(s) ${unresolved.map((n) => `#${String(n)}`).join(", ")} are among the capture's unresolved references: this repository holds no synchronized issue with that number, so no opening time. Whether one is the issue this change implements is read from the description: if it is, the order stays open (UNDETERMINED, never a timing judgement on another issue instead); if the description rules it out, it is no occasion.`,
			);
		}
		if (hints.length > 0) {
			directions.push(
				`The cell is decided by the issue's opening time against the earliest authored commit of the change (${contextFile(contextReference, "commits.json")}), never against the pull request's creation: a pull request is opened when the work is handed off, and the practice asks whether the plan preceded the work.`,
				"Compare the issue opening and earliest captured authored commit exactly. These dates establish the recorded order, not when all work began or why the issue was written.",
				...(first === undefined
					? [
							"If the complete captured commit record is empty or any commit lacks a usable authored date, the earliest time cannot be established and the timing is UNDETERMINED. The pull request's creation dates the handoff, not the start of work; it cannot replace the missing date. Missing commit capture is a collection gap, not UNDETERMINED.",
						]
					: []),
			);
			if (hints.some((hint) => hint.flags.namedBy === "Related to")) {
				directions.push(
					"An issue named only by `Related to` is the occasion only when the description or the issue shows this change implements part of it, not when the sentence is about other work. It was captured as a mention, not a closing candidate: nothing here says the issue closed or will close on merge.",
				);
			}
			if (hints.length > 1) {
				directions.push(
					`Several issues are named (${numbers}): judge the one this change implements, read from the description and the issues. If more than one remains plausible and their timing falls in different cells, do not choose the favourable one.`,
				);
			}
		}
	}
	return {
		hints,
		metrics: {
			namedIssues: named.size,
			unresolvedNamedIssues: unresolved.length,
			linkedItems: linked?.length ?? -1,
			commits: commits.length,
			issueOpenedAfterFirstCommitMinutes: Number.isNaN(earliestDeltaMinutes)
				? -1
				: Math.max(0, Math.round(earliestDeltaMinutes)),
		},
		directions,
	};
}

// Precompute HINTS for keeps-views-free-of-networking-and-persistence: locate I/O calls ADDED inside
// SwiftUI view types — requests, decoding, files, preferences, Core Data. SwiftData's view-side idiom
// (`@Query`, `modelContext.insert`) is the framework's own and is not listed. Each is a candidate the review places;
// a `load()` call on a store is not I/O in the view, and the script says which type a line lies in so
// the review does not have to find the declaration itself.
import { sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

/** A SwiftUI view: a type conforming to `View`, or an `App`/`Scene`, which also declare a body. */
const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

const IO_IN_VIEW: readonly SourcePattern[] = [
	["URLSession request", /\bURLSession\b|\bURLRequest\s*\(/u],
	["JSON coding", /\bJSON(?:Decoder|Encoder)\s*\(/u],
	["Core Data fetch", /\bNSFetchRequest\b|\.fetch\s*\(\s*NSFetchRequest/u],
	["UserDefaults access", /\bUserDefaults\b/u],
	["FileManager access", /\bFileManager\b/u],
	["Data(contentsOf:)", /\bData\(contentsOf:/u],
];

export default async function keepsViewsFreeOfNetworkingAndPersistence(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: IO_IN_VIEW,
		scope: SWIFTUI_VIEW,
		onlyInScope: true,
	});
	const directions: string[] = [...sampleNote(scan)];
	if (scan.matched > 0) {
		directions.push(
			`${scan.matched} candidate I/O calls were added inside or possibly inside view types. Read each hint's enclosing type. A line in a store or model is not the view's I/O. SwiftUI @AppStorage and @SceneStorage, Core Data @FetchRequest, and the supported SwiftData view-side APIs are not direct I/O.`,
		);
	}
	if (scan.filesWithoutCheckout > 0) {
		directions.push(
			`${scan.filesWithoutCheckout} Swift file(s) could not be read from the checkout; their hints carry enclosing=unknown and need the diff context to place.`,
		);
	}
	return {
		hints: scan.hints,
		metrics: {
			ioCallsInViews: scan.matched,
			viewLinesAdded: scan.linesInScope,
			swiftLinesAdded: scan.linesAdded,
			filesWithoutCheckout: scan.filesWithoutCheckout,
			filesScanned: scan.filesScanned,
			linesAdded: scan.linesAdded,
		},
		directions,
	};
}

// Precompute HINTS for owns-state-at-the-right-level: every state declaration and wiring ADDED in Swift
// files, placed in its enclosing type. The rules (local values @State, shared models observed once,
// edits through Binding, derived values computed) are the review's to apply; the script enumerates
// the declarations so none is missed and counts a model created inside a view type as a lead.
import { sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

const STATE_DECLARATIONS: readonly SourcePattern[] = [
	["@State creating an object", /@State(?:Object)?\b[^=]*=\s*[A-Z][A-Za-z0-9_]*\s*\(/u],
	["@State", /@State\b/u],
	["@StateObject", /@StateObject\b/u],
	["@ObservedObject", /@ObservedObject\b/u],
	["@Binding", /@Binding\b/u],
	["@Bindable", /@Bindable\b/u],
	["@Environment", /@Environment(?:Object)?\b/u],
	["@AppStorage", /@AppStorage\b/u],
	["@Query", /@Query\b/u],
	["@Observable type", /@Observable\b/u],
	["ObservableObject type", /\bObservableObject\b/u],
	["@Published", /@Published\b/u],
	[
		"mutable stored property",
		/^\s*(?:private\s+|fileprivate\s+|internal\s+)?var\s+[A-Za-z_][A-Za-z0-9_]*\s*(?::\s*[^{=\n]+)?(?:=\s*[^{\n]+)?\s*$/u,
	],
	["environment injection", /\.environment(?:Object)?\s*\(/u],
];

export default async function ownsStateAtTheRightLevel(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: STATE_DECLARATIONS,
		scope: SWIFTUI_VIEW,
		maxHints: 60,
	});
	const inViews = scan.hints.filter((h) => h.flags.inScope === true);
	const objectsCreatedInViews = inViews.filter(
		(h) => h.pattern === "@State creating an object" || h.pattern === "@StateObject",
	).length;
	const storedVarsInViews = inViews.filter((h) => h.pattern === "mutable stored property").length;
	const directions: string[] = [...sampleNote(scan)];
	if (scan.matched > 0) {
		directions.push(
			`${scan.matched} state declaration(s) or wiring line(s) added; ${inViews.length} of the listed rows lie inside view types. Walk each against the four rules.`,
		);
	}
	if (objectsCreatedInViews > 0) {
		directions.push(
			`${objectsCreatedInViews} object(s) created in a view's @State/@StateObject — check in the checkout whether a parent already owns an instance of the same type.`,
		);
	}
	if (storedVarsInViews > 0) {
		directions.push(
			`${storedVarsInViews} plain stored var(s) in a view type — a view mutating one of these without @State is a rule-1 lapse; a let-like var the view never mutates is not.`,
		);
	}
	return {
		hints: scan.hints,
		metrics: {
			stateDeclarationsAdded: scan.matched,
			stateDeclarationsInViews: inViews.length,
			objectsCreatedInViews,
			storedVarsInViews,
			filesWithoutCheckout: scan.filesWithoutCheckout,
			filesScanned: scan.filesScanned,
			linesAdded: scan.linesAdded,
		},
		directions,
	};
}

// Precompute HINTS for makes-ui-accessible-by-default: the interface lines ADDED in Swift files that the
// closed list in the criteria asks about — icon-only controls, images, fixed-size fonts, height caps,
// colour-only state — and the accessibility modifiers added alongside them. The review reads the view
// chain; the script counts what there is to read and how many labels arrived with it.
import { countLabel, sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

// Font.custom(_:size:) scales with the body style, custom(_:size:relativeTo:) with the style it names;
// only custom(_:fixedSize:) does not scale. Font.system(size:) is fixed at the size it is given.
const INTERFACE_LINES: readonly SourcePattern[] = [
	[
		"accessibility modifier",
		/\.accessibility(?:Label|Hint|Hidden|AddTraits|Value|Identifier)\s*\(/u,
	],
	["Label with text", /\bLabel\s*\(\s*"/u],
	["Image(systemName:)", /\bImage\s*\(\s*systemName:/u],
	["Image(asset)", /\bImage\s*\(\s*(?:"|decorative:|[a-z]\w*\.)/u],
	["fixed-size custom font", /\.custom\s*\([^)]*\bfixedSize:/u],
	["system font with a point size", /\.system\s*\(\s*size:/u],
	["scaled custom font", /\.custom\s*\([^)]*\bsize:/u],
	[
		"semantic font",
		/\.font\s*\(\s*\.(?:largeTitle|title[23]?|headline|subheadline|body|callout|footnote|caption2?)\b/u,
	],
	["height cap", /\.frame\s*\([^)]*\bheight:\s*\d/u],
	["lineLimit", /\.lineLimit\s*\(\s*\d/u],
	[
		"colour by state",
		/\.foregroundStyle\s*\(\s*[^)]*\?\s*\.(?:red|green|orange|yellow)|\.foregroundColor\s*\(\s*[^)]*\?\s*\.(?:red|green|orange|yellow)/u,
	],
	["Button", /\bButton\s*[({]/u],
	["Toggle", /\bToggle\s*\(/u],
];

export default async function makesUiAccessibleByDefault(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: INTERFACE_LINES,
		maxHints: 60,
	});
	const count = (label: string) => countLabel(scan, label);
	const metrics = {
		interfaceLinesAdded: scan.matched,
		symbolImages: count("Image(systemName:)"),
		assetImages: count("Image(asset)"),
		accessibilityModifiers: count("accessibility modifier"),
		fixedSizeCustomFonts: count("fixed-size custom font"),
		systemFontsWithPointSize: count("system font with a point size"),
		scaledCustomFonts: count("scaled custom font"),
		semanticFonts: count("semantic font"),
		heightCaps: count("height cap"),
		colourByState: count("colour by state"),
		filesWithoutCheckout: scan.filesWithoutCheckout,
		filesScanned: scan.filesScanned,
		linesAdded: scan.linesAdded,
	};
	const directions: string[] = [...sampleNote(scan)];
	if (metrics.symbolImages + metrics.assetImages > 0) {
		directions.push(
			`${metrics.symbolImages + metrics.assetImages} image(s) added against ${metrics.accessibilityModifiers} accessibility modifier(s) — for each image inside a Button, Toggle or tap gesture, read the whole view chain for a label or a Label title.`,
		);
	}
	if (metrics.fixedSizeCustomFonts > 0) {
		directions.push(
			`${metrics.fixedSizeCustomFonts} custom font(s) with fixedSize: added — these do not scale with the user's text size.`,
		);
	}
	if (metrics.systemFontsWithPointSize > 0) {
		directions.push(
			`${metrics.systemFontsWithPointSize} system font(s) with a point size added — fixed unless the size itself scales (a @ScaledMetric value); read where each size comes from. A custom font given size: scales with the body style and is not fixed.`,
		);
	}
	if (metrics.heightCaps > 0) {
		directions.push(
			`${metrics.heightCaps} height cap(s) added — a cap clips only when the container holds text.`,
		);
	}
	return { hints: scan.hints, metrics, directions };
}

// Precompute HINTS for uses-structured-concurrency-safely: every concurrency construct ADDED in Swift
// files, placed in its enclosing type, and the lines of the project files that mention a default actor
// isolation. Whether the work must outlive the view, and whether a mutation lands on the main actor, is
// the review's to decide from the checkout.
import { readFile } from "node:fs/promises";
import path from "node:path";

import { globFilesSync } from "../lib/files.ts";
import { countLabel, sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

const CONCURRENCY: readonly SourcePattern[] = [
	["Task.detached", /\bTask\.detached\b/u],
	["stored task handle", /(?:let|var)\s+\w+\s*(?::\s*Task<[^>]*>)?\s*=\s*Task\s*[{(]/u],
	["Task { }", /\bTask\s*(?:\(priority:[^)]*\))?\s*\{/u],
	[".task modifier", /\.task\s*(?:\(id:[^)]*\))?\s*\{/u],
	[".onAppear", /\.onAppear\s*\{/u],
	["DispatchQueue", /\bDispatchQueue\b/u],
	["@MainActor", /@MainActor\b/u],
	["MainActor.run", /\bMainActor\.run\b/u],
	["actor declaration", /^\s*(?:\w+\s+)*actor\s+\w+/u],
	["async function", /\bfunc\s+\w+[^{]*\basync\b/u],
	["await", /\bawait\b/u],
];

/** Text naming a default actor isolation: an Xcode build setting or a SwiftPM target setting. */
const DEFAULT_ISOLATION = /SWIFT_DEFAULT_ACTOR_ISOLATION\s*[:=]|defaultIsolation\s*\(/u;

/**
 * Lines of the first few project files that mention a default actor isolation, as `path:line text`. The
 * setting belongs to one target or SwiftPM module and build configuration, and a line may be commented
 * out, so a line found here is a place to read, not the isolation of any changed type.
 */
async function defaultIsolationLines(repoPath: string): Promise<string[]> {
	let files: string[];
	try {
		files = [
			...globFilesSync("**/project.yml", repoPath),
			...globFilesSync("**/project.yaml", repoPath),
			...globFilesSync("**/*.xcodeproj/project.pbxproj", repoPath),
			...globFilesSync("**/Package.swift", repoPath),
		].filter((f) => !/(?:^|\/)(?:Pods|\.build|DerivedData|Carthage)\//u.test(f));
	} catch {
		return [];
	}
	const found: string[] = [];
	for (const file of files.slice(0, 20)) {
		let text: string;
		try {
			text = await readFile(path.join(repoPath, file), "utf8");
		} catch {
			continue;
		}
		for (const [index, line] of text.split(/\r?\n/u).entries()) {
			if (DEFAULT_ISOLATION.test(line)) {
				found.push(`${file}:${String(index + 1)} ${line.trim().slice(0, 120)}`);
			}
		}
	}
	return found.slice(0, 10);
}

export default async function usesStructuredConcurrencySafely(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: CONCURRENCY,
		scope: SWIFTUI_VIEW,
		maxHints: 60,
	});
	const count = (label: string) => countLabel(scan, label);
	const unstructuredInViews = scan.hints.filter(
		(h) => h.pattern === "Task { }" && h.flags.inScope === true,
	).length;
	const metrics = {
		concurrencyLinesAdded: scan.matched,
		taskBlocks: count("Task { }"),
		taskBlocksInListedViewRows: unstructuredInViews,
		taskModifiers: count(".task modifier"),
		detachedTasks: count("Task.detached"),
		dispatchQueues: count("DispatchQueue"),
		mainActorMarks: count("@MainActor") + count("MainActor.run"),
		filesWithoutCheckout: scan.filesWithoutCheckout,
		filesScanned: scan.filesScanned,
		linesAdded: scan.linesAdded,
	};
	const directions: string[] = [...sampleNote(scan)];
	if (unstructuredInViews > 0) {
		directions.push(
			`${unstructuredInViews} Task { } block(s) added inside view types — read the lifetime each needs: work tied to the view belongs to a lifecycle that cancels it, while a Task started from a user action may legitimately finish after the view is gone.`,
		);
	}
	if (metrics.detachedTasks + metrics.dispatchQueues > 0) {
		directions.push(
			`${metrics.detachedTasks} detached task(s) and ${metrics.dispatchQueues} dispatch queue use(s) — read whether the code shows a need for independent execution or scheduling; no written reason is required when it does.`,
		);
	}
	if (scan.matched > 0) {
		const settings = await defaultIsolationLines(repoPath);
		directions.push(
			settings.length > 0
				? `Default actor isolation text in project files: ${settings.join("; ")}. Each applies only to its own target or SwiftPM module and build configuration, and a commented line sets nothing: read which target and configuration build the changed file before relying on any of them.`
				: "No default actor isolation text was found in the project files read, which leaves the module's default unknown rather than nonisolated.",
			"A type's isolation comes from its declaration, its module's setting or what it inherits. A missing @MainActor on an added line does not by itself put a mutation off the main actor. Check the SDK before relying on inherited SwiftUI View isolation. Swallowed failures belong to handles-errors-instead-of-swallowing-them, not this practice.",
		);
	}
	return { hints: scan.hints, metrics, directions };
}

// Precompute HINTS for ships-a-preview-with-each-new-view: the view types this change declares and the
// previews it adds, per file. The pairing is a fact the review checks; whether a preview's data is
// representative is the review's to read.
import { isCommentLine } from "../lib/declarations.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const VIEW_DECLARATION =
	/^\s*(?:@\w+\s+)*(?:(?:public|private|fileprivate|internal)\s+)?struct\s+(?<name>[A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*:\s*[^{]*\bView\b/u;
const PREVIEW = /^\s*#Preview\b|:\s*PreviewProvider\b/u;

export default function shipsAPreviewWithEachNewView(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	let newViews = 0;
	let previewsAdded = 0;
	let filesWithNewViewAndNoPreview = 0;
	for (const [path, df] of diffFiles) {
		if (languageOf(path) !== "swift" || isTestPath(path)) {
			continue;
		}
		let views = 0;
		let previews = 0;
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, "swift")) {
				continue;
			}
			const view = VIEW_DECLARATION.exec(content);
			if (view) {
				views += 1;
				hints.push({
					file: path,
					line,
					pattern: "new view type",
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: { name: view.groups?.name ?? "" },
				});
			} else if (PREVIEW.test(content)) {
				previews += 1;
				hints.push({
					file: path,
					line,
					pattern: "preview",
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: {},
				});
			}
		}
		newViews += views;
		previewsAdded += previews;
		if (views > 0 && previews === 0) {
			filesWithNewViewAndNoPreview += 1;
		}
	}
	const directions: string[] = [];
	if (newViews > 0) {
		directions.push(
			`${newViews} new view type(s) declared and ${previewsAdded} preview(s) added; ${filesWithNewViewAndNoPreview} file(s) declare a view and add no preview — a preview may live in another file of the change, so scan the whole diff before deciding. These counts pair no preview with a view. Read the previews and view bodies to trace the presentation coverage described in the criteria, including nested views and content delegated by an effect-only owner.`,
		);
	}
	return {
		hints: hints.slice(0, 40),
		metrics: { newViews, previewsAdded, filesWithNewViewAndNoPreview },
		directions,
	};
}

// Precompute HINTS for declares-permissions-truthfully-at-point-of-use: the permission-related references
// and authorization requests ADDED in Swift files, and the usage-description keys located in the change
// or in the first plist/project files of the checkout, each with its path. A reference names a type or
// call to inspect; it does not show that the change requests restricted access. A key located in some file
// does not show that the target in question declares it, nor does a key not located show that it does
// not; the review reads the target, the actual API and the description.
import { readFile } from "node:fs/promises";
import path from "node:path";

import { globFilesSync } from "../lib/files.ts";
import { countLabel, sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

// reference kind -> [a permission-related type or call to inspect, usage keys that may declare its access].
// A match is a place to look, not access: a type named in a signature or conformance requests nothing,
// the system photo picker needs no library permission, and an image picker reaches the camera only when
// the camera is its source.
const PERMISSION_REFERENCES: readonly [string, RegExp, string[]][] = [
	[
		"Location",
		/\bCLLocationManager\b/u,
		["NSLocationWhenInUseUsageDescription", "NSLocationAlwaysAndWhenInUseUsageDescription"],
	],
	[
		"Camera",
		/\bAVCaptureDevice\b|\bAVCaptureSession\b|\bsourceType\s*[:=]\s*\.camera\b|\.isSourceTypeAvailable\s*\(\s*\.camera\s*\)/u,
		["NSCameraUsageDescription"],
	],
	[
		"Microphone",
		/\bAVAudioRecorder\b|\bAVAudioSession\b.*record|\.record\(/u,
		["NSMicrophoneUsageDescription"],
	],
	[
		"PhotoLibrary",
		/\bPHPhotoLibrary\b|\bPHAsset\b/u,
		["NSPhotoLibraryUsageDescription", "NSPhotoLibraryAddUsageDescription"],
	],
	["Notifications", /\bUNUserNotificationCenter\b/u, []],
	[
		"Calendar",
		/\bEKEventStore\b/u,
		[
			"NSCalendarsUsageDescription",
			"NSCalendarsFullAccessUsageDescription",
			"NSCalendarsWriteOnlyAccessUsageDescription",
		],
	],
	["Contacts", /\bCNContactStore\b/u, ["NSContactsUsageDescription"]],
	[
		"HealthKit",
		/\bHKHealthStore\b/u,
		["NSHealthShareUsageDescription", "NSHealthUpdateUsageDescription"],
	],
	["Tracking", /\bATTrackingManager\b/u, ["NSUserTrackingUsageDescription"]],
	[
		"Bluetooth",
		/\bCBCentralManager\b|\bCBPeripheralManager\b/u,
		["NSBluetoothAlwaysUsageDescription"],
	],
	["Motion", /\bCMMotionActivityManager\b|\bCMPedometer\b/u, ["NSMotionUsageDescription"]],
	["Speech", /\bSFSpeechRecognizer\b/u, ["NSSpeechRecognitionUsageDescription"]],
	["LocalNetwork", /\bNWBrowser\b|\bNetService\b/u, ["NSLocalNetworkUsageDescription"]],
];

const REQUEST: readonly SourcePattern[] = [
	[
		"authorization request",
		/\brequest(?:WhenInUse|Always)?Authorization\b|\brequestAccess\b|\brequestTrackingAuthorization\b|\bPHPhotoLibrary\.requestAuthorization\b/u,
	],
	...PERMISSION_REFERENCES.map(([kind, re]): SourcePattern => [
		`permission-related reference ${kind}`,
		re,
	]),
];

const USAGE_KEY = /\b(?<key>NS\w+UsageDescription)\b/gu;

/** How many plist/project files of the checkout are read for keys. */
const PROJECT_FILES_READ = 20;

interface CheckoutKeys {
	keys: Map<string, string[]>;
	filesFound: number;
	filesRead: number;
	unreadable: number;
}

async function usageKeysInCheckout(repoPath: string): Promise<CheckoutKeys> {
	const keys = new Map<string, string[]>();
	let files: string[] = [];
	try {
		files = [
			...globFilesSync("**/Info.plist", repoPath),
			...globFilesSync("**/project.yml", repoPath),
			...globFilesSync("**/project.yaml", repoPath),
			...globFilesSync("**/*.xcodeproj/project.pbxproj", repoPath),
		].filter((f) => !/(?:^|\/)(?:Pods|\.build|DerivedData|Carthage)\//u.test(f));
	} catch {
		// no readable checkout: no file read, so no key located
	}
	let unreadable = 0;
	const read = files.slice(0, PROJECT_FILES_READ);
	for (const file of read) {
		let text: string;
		try {
			text = await readFile(path.join(repoPath, file), "utf8");
		} catch {
			unreadable += 1;
			continue;
		}
		for (const match of text.matchAll(USAGE_KEY)) {
			const key = match.groups?.key ?? "";
			keys.set(key, [...new Set([...(keys.get(key) ?? []), file])]);
		}
	}
	return { keys, filesFound: files.length, filesRead: read.length - unreadable, unreadable };
}

export default async function declaresPermissionsTruthfullyAtPointOfUse(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: REQUEST,
	});
	const hints: Hint[] = [...scan.hints];
	// Usage keys the change itself adds, in any file.
	const keysInChange = new Map<string, string>();
	for (const [file, df] of diffFiles) {
		if (!/Info\.plist$|project\.ya?ml$|project\.pbxproj$/u.test(file)) {
			continue;
		}
		for (const [line, content] of df.addedLines) {
			for (const match of content.matchAll(USAGE_KEY)) {
				const key = match.groups?.key ?? "";
				keysInChange.set(key, file);
				hints.push({
					file,
					line,
					pattern: "usage key added",
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: { key },
				});
			}
		}
	}
	const checkout = await usageKeysInCheckout(repoPath);
	const references = PERMISSION_REFERENCES.filter(([kind]) =>
		scan.counts.has(`permission-related reference ${kind}`),
	);
	const located = (keys: string[]) =>
		keys.flatMap((key) => {
			const inChange = keysInChange.get(key);
			const where = [
				...new Set([
					...(inChange === undefined ? [] : [inChange]),
					...(checkout.keys.get(key) ?? []),
				]),
			];
			return where.length === 0 ? [] : [`${key} (${where.join(", ")})`];
		});
	const directions: string[] = [...sampleNote(scan)];
	if (references.length > 0) {
		const read = `${String(checkout.filesRead)} of ${String(checkout.filesFound)} plist/project file(s) read${checkout.unreadable > 0 ? `, ${String(checkout.unreadable)} unreadable` : ""}`;
		directions.push(
			`Permission-related references to inspect: ${references
				.map(([kind, , keys]) => {
					if (keys.length === 0) {
						return `${kind} (no usage key applies)`;
					}
					const found = located(keys);
					return `${kind} — keys located: ${found.length > 0 ? found.join("; ") : "none"}`;
				})
				.join(
					". ",
				)}. Searched the change and ${read}. A key located in a file does not show the target declares it, and a key not located does not show it is missing: read the target's own Info.plist or build settings, and the key the actual API and deployment target require.`,
		);
	}
	const requests = countLabel(scan, "authorization request");
	if (requests > 0) {
		directions.push(
			`${requests} authorization requests were added. For each request, read the enclosing flag and the call chain. Decide whether it runs when the feature is reached or earlier. A root view can be the feature that needs authorization.`,
		);
	}
	return {
		hints: hints.slice(0, 40),
		metrics: {
			permissionReferenceKinds: references.length,
			authorizationRequests: requests,
			usageKeysAdded: keysInChange.size,
			usageKeysLocatedInCheckout: checkout.keys.size,
			projectFilesRead: checkout.filesRead,
			filesScanned: scan.filesScanned,
			linesAdded: scan.linesAdded,
		},
		directions,
	};
}

// Precompute HINTS for uses-adaptive-colors-for-every-appearance: the color expressions ADDED inside
// SwiftUI view types, each under the first shape its text shows, and for each named asset color whether
// its colorset carries a dark appearance. A shape is spelling, not a type: `.green` given to
// `foregroundStyle` is SwiftUI's context-dependent standard color, `Color(.green)` converts UIKit's fixed
// `UIColor.green`, and a name the app defines is whatever its definition says. Only the shapes whose
// spelling fixes the kind — components, white or black, semantic styles, materials, the accent — are
// counted as literal or adaptive; the rest are left to the review to classify. The role a color plays —
// content over a fill, or a background that bakes in one appearance — is the review's to read from the
// modifier chain.
import { readFile } from "node:fs/promises";
import path from "node:path";

import { globFilesSync } from "../lib/files.ts";
import { isJsonObject } from "../lib/practice-contract.ts";
import { countLabel, sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

// First match wins on a line, so the order runs from the shapes whose spelling fixes the kind to those it
// does not.
const COLORS: readonly SourcePattern[] = [
	[
		"fixed components",
		/\bColor\s*\(\s*(?:red|hue|white|\.sRGB|\.displayP3|hex)\s*:|\bColor\s*\(\s*"#|\bUIColor\s*\(\s*(?:red|white|hue|displayP3Red)\s*:/u,
	],
	["literal white/black", /\b(?:UI)?Color\.(?:white|black)\b|[:(,]\s*\.(?:white|black)\b/u],
	["UIKit color", /\bUIColor\s*\.\s*[a-z]\w*|\bColor\s*\(\s*uiColor:\s*\.[a-z]\w*/u],
	// `Color(_:bundle:)`: the bundle is optional, and without one the app's main bundle is searched.
	["named asset", /\bColor\s*\(\s*"[^"]+"\s*(?:\)|,\s*bundle\s*:)/u],
	["Color from a value", /\bColor\s*\(\s*\.[a-z]\w*/u],
	["semantic", /\.(?:primary|secondary|tertiary|quaternary)\b/u],
	["material", /\.(?:ultraThin|thin|regular|thick|ultraThick|bar)Material\b/u],
	["accent", /\.accentColor\b|[:(,]\s*\.tint\b(?!\s*\()/u],
	["SwiftUI Color member", /\bColor\s*\.\s*[a-z]\w*/u],
	[
		"member given to a color modifier",
		/\.(?:foregroundStyle|foregroundColor|background|fill|tint|stroke|strokeBorder|border)\s*\(\s*\.[a-z]\w*/u,
	],
];

/** The shapes whose spelling leaves the kind open: a type or a definition decides it. */
const TO_CLASSIFY = [
	"UIKit color",
	"Color from a value",
	"SwiftUI Color member",
	"member given to a color modifier",
] as const;

/** Whether a colorset carries a dark appearance; "unknown" when it cannot be read as one. */
type DarkAppearance = boolean | "unknown";

function darkAppearanceOf(source: string): DarkAppearance {
	let parsed: unknown;
	try {
		parsed = JSON.parse(source);
	} catch {
		return "unknown";
	}
	if (!isJsonObject(parsed) || !Array.isArray(parsed.colors) || parsed.colors.length === 0) {
		return "unknown";
	}
	// Every entry is read before a missing dark appearance is a fact: one entry of another shape could
	// be the dark one.
	let dark = false;
	for (const entry of parsed.colors) {
		if (!isJsonObject(entry)) {
			return "unknown";
		}
		if (entry.appearances === undefined) {
			continue;
		}
		if (
			!Array.isArray(entry.appearances) ||
			!entry.appearances.every(
				(appearance) =>
					isJsonObject(appearance) &&
					typeof appearance.appearance === "string" &&
					typeof appearance.value === "string",
			)
		) {
			return "unknown";
		}
		dark ||= entry.appearances.some(
			(appearance) =>
				isJsonObject(appearance) &&
				appearance.appearance === "luminosity" &&
				appearance.value === "dark",
		);
	}
	return dark;
}

/** The bundle a `Color("name", bundle:)` names, or null for the main bundle it searches without one. */
function bundleOf(context: string): string | null {
	const bundle = /Color\s*\(\s*"[^"]+"\s*,\s*bundle\s*:\s*(?<bundle>[^,)]+(?:\([^)]*\))?)/u.exec(
		context,
	)?.groups?.bundle;
	return bundle === undefined || /^(?:\.main|Bundle\.main|nil)\s*$/u.test(bundle)
		? null
		: bundle.trim();
}

/** How many colorsets of the checkout are read; a name beyond them is unknown. */
const COLORSETS_READ = 200;

interface AssetColors {
	/** Every colorset path of the checkout by color name, read or not. */
	paths: Map<string, string[]>;
	/** The appearances of the colorsets read, by path. */
	read: Map<string, DarkAppearance>;
}

function colorNameOf(file: string): string {
	return (
		file
			.split("/")
			.at(-2)
			?.replace(/\.colorset$/u, "") ?? ""
	);
}

/**
 * The appearance of a named color, from its one colorset: the only one of exactly that name, else the
 * only one whose name differs in case alone. Two candidates anywhere in the checkout, or one not read,
 * leave it unknown, since nothing here says which target's catalog the view uses.
 */
function appearanceOf({ paths, read }: AssetColors, name: string): DarkAppearance {
	const exact = paths.get(name);
	const candidates =
		exact ??
		[...paths.entries()]
			.filter(([n]) => n.toLowerCase() === name.toLowerCase())
			.flatMap(([, files]) => files);
	const [only] = candidates;
	return candidates.length === 1 && only !== undefined ? (read.get(only) ?? "unknown") : "unknown";
}

async function assetColors(repoPath: string): Promise<AssetColors> {
	let all: string[] = [];
	try {
		all = globFilesSync("**/*.xcassets/**/*.colorset/Contents.json", repoPath);
	} catch {
		// no readable checkout: no colorset read
	}
	const paths = new Map<string, string[]>();
	for (const file of all) {
		const name = colorNameOf(file);
		paths.set(name, [...(paths.get(name) ?? []), file]);
	}
	const read = new Map<string, DarkAppearance>();
	for (const file of all.slice(0, COLORSETS_READ)) {
		let dark: DarkAppearance = "unknown";
		try {
			dark = darkAppearanceOf(await readFile(path.join(repoPath, file), "utf8"));
		} catch {
			// an unreadable colorset is not a fact about its appearances
		}
		read.set(file, dark);
	}
	return { paths, read };
}

export default async function usesAdaptiveColorsForEveryAppearance(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: COLORS,
		scope: SWIFTUI_VIEW,
		onlyInScope: true,
	});
	const assets = await assetColors(repoPath);
	const colorsetsFound = [...assets.paths.values()].reduce((sum, files) => sum + files.length, 0);
	const hints: Hint[] = scan.hints.map((h) => {
		if (h.pattern !== "named asset" && h.pattern !== "Color from a value") {
			return h;
		}
		const name =
			/Color\s*\(\s*"(?<name>[^"]+)"/u.exec(h.context)?.groups?.name ??
			/Color\s*\(\s*\.(?<name>\w+)/u.exec(h.context)?.groups?.name ??
			"";
		// Which catalog another bundle, such as a package's `.module`, holds is not read here.
		const bundle = h.pattern === "named asset" ? bundleOf(h.context) : null;
		return {
			...h,
			flags: {
				...h.flags,
				asset: name,
				...(bundle === null ? {} : { bundle }),
				hasDarkAppearance: bundle === null ? appearanceOf(assets, name) : "unknown",
			},
		};
	});
	const inOtherBundles = hints.filter((h) => h.flags.bundle !== undefined).length;
	const literals = countLabel(scan, "fixed components") + countLabel(scan, "literal white/black");
	const toClassify = TO_CLASSIFY.reduce((sum, label) => sum + countLabel(scan, label), 0);
	const systemAdaptive =
		countLabel(scan, "semantic") + countLabel(scan, "material") + countLabel(scan, "accent");
	const namedAssets = countLabel(scan, "named asset");
	const assetsWithoutDarkAppearance = hints.filter(
		(h) => h.flags.hasDarkAppearance === false,
	).length;
	const directions: string[] = [...sampleNote(scan)];
	if (literals > 0) {
		directions.push(
			`Found ${literals} literal colors, ${systemAdaptive} system-adaptive colors and ${namedAssets} named asset colors added in view types. For each literal, read the modifier chain. Text over a fill the same view sets is content. A literal background or text on a system background can fix one appearance. A translucent scrim over an image is content, not an adaptive screen background.`,
		);
	}
	if (toClassify > 0) {
		directions.push(
			`${toClassify} added line(s) name a color whose spelling does not settle its kind — a UIKit color, \`Color(.name)\`, a \`Color\` member or a member given to a color modifier. Read the type it resolves to and, for a name the app defines, its definition: SwiftUI's standard colors and UIKit's dynamic colors change with the appearance, UIKit's fixed constants do not.`,
		);
	}
	if (scan.hints.length > 0) {
		directions.push(
			"Each line is listed once, under the first shape its text shows: enumerate every color a listed line holds.",
		);
	}
	if (assetsWithoutDarkAppearance > 0) {
		directions.push(
			`${assetsWithoutDarkAppearance} listed named asset color(s) whose colorset has no dark luminosity entry — read its color values and how it is used before judging whether it adapts.`,
		);
	}
	if (inOtherBundles > 0) {
		directions.push(
			`${String(inOtherBundles)} listed named asset color(s) are looked up in a bundle other than the main one: which asset catalog that bundle holds was not resolved, so their dark appearance is unknown until the catalog is located.`,
		);
	}
	if (namedAssets > 0 && colorsetsFound > COLORSETS_READ) {
		directions.push(
			`The checkout holds ${String(colorsetsFound)} colorsets and the first ${String(COLORSETS_READ)} were read: a named color whose colorset was not read is unknown, not missing.`,
		);
	}
	return {
		hints,
		metrics: {
			literalColors: literals,
			systemAdaptiveColors: systemAdaptive,
			namedAssetColors: namedAssets,
			colorsToClassify: toClassify,
			assetsWithoutDarkAppearance,
			assetColorsInCheckout: colorsetsFound,
			filesWithoutCheckout: scan.filesWithoutCheckout,
			filesScanned: scan.filesScanned,
			linesAdded: scan.linesAdded,
		},
		directions,
	};
}
